async fn delete_knowledge_base(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(name): Path<String>,
) -> impl IntoResponse {
    let payload = match require_auth(&state, &headers) {
        Ok(payload) => payload,
        Err(response) => return (*response).into_response(),
    };
    let access = match resolve_knowledge_access(&state, &payload, &name) {
        Ok(access) => access,
        Err(error) => return error.into_response(),
    };
    if let Err(error) = ensure_knowledge_access_writable(&access) {
        return error.into_response();
    }
    if name == BUILTIN_KNOWLEDGE_BASE {
        return api_error(
            StatusCode::BAD_REQUEST,
            "The built-in Socartes course cannot be deleted",
        )
        .into_response();
    }

    let path = knowledge_base_dir(&state, &name);
    if !path.exists() {
        return api_error(StatusCode::NOT_FOUND, "Knowledge base not found").into_response();
    }

    match fs::remove_dir_all(path) {
        Ok(()) => Json(json!({ "status": "ok" })).into_response(),
        Err(error) => api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to delete knowledge base: {error}"),
        )
        .into_response(),
    }
}

