fn parse_tutorbot_team_plan_json(text: &str) -> Option<Value> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return None;
    }
    let unfenced = if trimmed.starts_with("```") {
        let after_first_line = trimmed
            .split_once('\n')
            .map(|(_, rest)| rest)
            .unwrap_or(trimmed);
        after_first_line
            .rsplit_once("```")
            .map(|(body, _)| body.trim())
            .unwrap_or(after_first_line.trim())
    } else {
        trimmed
    };
    serde_json::from_str::<Value>(unfenced)
        .ok()
        .filter(Value::is_object)
        .or_else(|| {
            let start = unfenced.find('{')?;
            let end = unfenced.rfind('}')?;
            (end > start)
                .then(|| &unfenced[start..=end])
                .and_then(|candidate| serde_json::from_str::<Value>(candidate).ok())
                .filter(Value::is_object)
        })
}

fn tutorbot_team_plan_has_dependency_cycle(tasks: &[Value]) -> bool {
    let graph = tasks
        .iter()
        .filter_map(|task| {
            let id = task["id"].as_str()?.to_string();
            let deps = task["depends_on"]
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(|dep| dep.as_str().map(ToString::to_string))
                .collect::<Vec<_>>();
            Some((id, deps))
        })
        .collect::<HashMap<_, _>>();

    fn visit(
        node: &str,
        graph: &HashMap<String, Vec<String>>,
        visiting: &mut HashSet<String>,
        visited: &mut HashSet<String>,
    ) -> bool {
        if visited.contains(node) {
            return false;
        }
        if !visiting.insert(node.to_string()) {
            return true;
        }
        if let Some(deps) = graph.get(node) {
            for dep in deps {
                if graph.contains_key(dep) && visit(dep, graph, visiting, visited) {
                    return true;
                }
            }
        }
        visiting.remove(node);
        visited.insert(node.to_string());
        false
    }

    let mut visiting = HashSet::new();
    let mut visited = HashSet::new();
    graph
        .keys()
        .any(|node| visit(node, &graph, &mut visiting, &mut visited))
}

fn normalize_tutorbot_team_plan_payload(
    payload: &Value,
    selection: &ChatRuntimeSelection,
) -> Result<TutorbotTeamPlan, String> {
    let raw_members = payload["members"]
        .as_array()
        .ok_or_else(|| "members must be a list".to_string())?;
    let raw_tasks = payload["tasks"]
        .as_array()
        .ok_or_else(|| "tasks must be a non-empty list".to_string())?;
    if raw_members.len() < 2 {
        return Err("at least 2 members are required".to_string());
    }
    if raw_tasks.is_empty() {
        return Err("tasks must be a non-empty list".to_string());
    }

    let mut seen_members = HashSet::new();
    let mut members = Vec::new();
    for (index, member) in raw_members.iter().take(3).enumerate() {
        let raw_name = member["name"].as_str().unwrap_or_default().trim();
        let name = safe_storage_component(raw_name)
            .filter(|name| !seen_members.contains(name))
            .unwrap_or_else(|| format!("member{}", index + 1));
        if !seen_members.insert(name.clone()) {
            return Err("duplicate member names".to_string());
        }
        let role = member["role"]
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or("Worker");
        members.push(json!({
            "name": name,
            "role": role,
            "model": selection.model.as_str(),
            "status": "active"
        }));
    }
    if members.len() < 2 {
        return Err("at least 2 members are required".to_string());
    }
    let member_names = members
        .iter()
        .filter_map(|member| member["name"].as_str().map(ToString::to_string))
        .collect::<HashSet<_>>();

    let mut task_ids = Vec::new();
    let mut seen_task_ids = HashSet::new();
    for (index, task) in raw_tasks.iter().enumerate() {
        let raw_id = task["id"]
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string)
            .unwrap_or_else(|| format!("t{}", index + 1));
        let id = safe_storage_component(&raw_id).ok_or_else(|| "invalid task id".to_string())?;
        if !seen_task_ids.insert(id.clone()) {
            return Err("duplicate task ids".to_string());
        }
        task_ids.push(id);
    }
    let task_id_set = task_ids.iter().cloned().collect::<HashSet<_>>();

    let mut tasks = Vec::new();
    for (index, task) in raw_tasks.iter().enumerate() {
        let title = task["title"]
            .as_str()
            .map(str::trim)
            .ok_or_else(|| "no valid tasks found".to_string())?
            .to_string();
        if title.is_empty() {
            return Err("no valid tasks found".to_string());
        }
        let description = task["description"]
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or(title.as_str());
        let owner = task["owner"]
            .as_str()
            .map(str::trim)
            .filter(|value| member_names.contains(*value))
            .map(|value| json!(value))
            .unwrap_or(Value::Null);
        let depends_on = task["depends_on"]
            .as_array()
            .into_iter()
            .flatten()
            .filter_map(|value| value.as_str().map(str::trim))
            .filter(|value| task_id_set.contains(*value))
            .map(ToString::to_string)
            .collect::<Vec<_>>();
        tasks.push(json!({
            "id": task_ids[index],
            "title": title,
            "description": description,
            "owner": owner,
            "status": "pending",
            "depends_on": depends_on,
            "plan": null,
            "result": null,
            "requires_approval": task["requires_approval"].as_bool().unwrap_or(false)
        }));
    }
    if tutorbot_team_plan_has_dependency_cycle(&tasks) {
        return Err("task dependency graph has a cycle".to_string());
    }
    Ok(TutorbotTeamPlan {
        mission: payload["mission"]
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or("Complete the requested mission.")
            .to_string(),
        members,
        tasks,
        notes: payload["notes"]
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(|value| {
                if value.ends_with('\n') {
                    value.to_string()
                } else {
                    format!("{value}\n")
                }
            })
            .unwrap_or_else(|| "# Team Notes\n".to_string()),
        planning: json!({
            "source": "provider",
            "profile_id": selection.profile_id.as_str(),
            "model_id": selection.model_id.as_str(),
            "model": selection.model.as_str(),
            "provider": selection.binding.as_str()
        }),
    })
}

fn tutorbot_team_plan_body(
    selection: &ChatRuntimeSelection,
    mission: &str,
    repair_error: Option<&str>,
) -> Value {
    let mut user = format!("Goal:\n{mission}");
    if let Some(repair_error) = repair_error.filter(|value| !value.trim().is_empty()) {
        user.push_str(&format!(
            "\n\nPrevious output error: {repair_error}\nFix and output valid JSON only."
        ));
    }
    json!({
        "model": selection.model.as_str(),
        "messages": [
            {
                "role": "system",
                "content": "You are planning a tiny Socartes execution team. Return only JSON. Return strict JSON only. Schema: {\"mission\": string, \"members\": [{\"name\": string, \"role\": string, \"model\": string?}], \"tasks\": [{\"id\": string, \"title\": string, \"description\": string, \"owner\": string?, \"depends_on\": [string]?, \"requires_approval\": boolean?}], \"notes\": string}. Rules: 2-3 members only. Tasks must be actionable and coherent."
            },
            {
                "role": "user",
                "content": user
            }
        ],
        "temperature": 0.1,
        "max_tokens": 1400,
        "stream": false
    })
}

async fn tutorbot_provider_team_plan(
    state: &AppState,
    config: &Value,
    mission: &str,
) -> Option<TutorbotTeamPlan> {
    let selection =
        active_chat_selection(&load_settings_catalog(state), &config["llm_selection"]).ok()??;
    let mut repair_error: Option<String> = None;
    for _ in 0..2 {
        let body = tutorbot_team_plan_body(&selection, mission, repair_error.as_deref());
        let response = call_chat_completion_provider(&selection, body).await.ok()?;
        let content = response.content.as_deref().unwrap_or_default();
        let Some(payload) = parse_tutorbot_team_plan_json(content) else {
            repair_error = Some("Malformed JSON.".to_string());
            continue;
        };
        match normalize_tutorbot_team_plan_payload(&payload, &selection) {
            Ok(plan) => return Some(plan),
            Err(error) => repair_error = Some(error),
        }
    }
    None
}

async fn start_tutorbot_team(
    state: &AppState,
    bot_id: &str,
    session_key: &str,
    config: &Value,
    mission: &str,
) -> Result<TutorbotCommandResponse, ApiError> {
    let mission = mission.trim();
    if mission.is_empty() {
        return Ok(tutorbot_team_command_text(tutorbot_team_usage_text()));
    }

    let plan = tutorbot_provider_team_plan(state, config, mission)
        .await
        .unwrap_or_else(|| deterministic_tutorbot_team_plan(mission));
    let session_dir = tutorbot_team_session_dir(state, bot_id, session_key);
    let run_id = format!("run-{}", current_epoch_millis());
    let mut id_suffix = uuid::Uuid::new_v4().simple().to_string();
    id_suffix.truncate(8);
    let team_id = format!("nano-{id_suffix}");
    let run_dir = session_dir.join(&run_id);
    for member in &plan.members {
        let Some(name) = member["name"].as_str().and_then(safe_storage_component) else {
            continue;
        };
        fs::create_dir_all(run_dir.join("workers").join(name))
            .map_err(|error| tutorbot_team_runtime_error("create", error))?;
    }

    let now = now_rfc3339();
    let config = json!({
        "team_id": team_id,
        "run_id": run_id,
        "mission": plan.mission,
        "lead": "lead",
        "members": plan.members,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "session_key": session_key,
        "planning": plan.planning
    });
    let tasks = Value::Array(plan.tasks);
    write_pretty_json_file(&run_dir.join("config.json"), &config, "write config for")?;
    write_pretty_json_file(&run_dir.join("tasks.json"), &tasks, "write tasks for")?;
    fs::write(run_dir.join("NOTES.md"), plan.notes)
        .map_err(|error| tutorbot_team_runtime_error("write notes for", error))?;
    append_tutorbot_team_event(
        &run_dir,
        "team_started",
        &format!(
            "Started nano team for goal: {}",
            config["mission"].as_str().unwrap_or(mission)
        ),
        json!({
            "team_id": config["team_id"],
            "mission": config["mission"],
            "plan_source": config["planning"]["source"]
        }),
    )?;
    update_tutorbot_team_metadata(state, bot_id, session_key, Some(true))?;

    let team_id = config["team_id"].as_str().unwrap_or("nano-team");
    let worker_count = config["members"]
        .as_array()
        .map(Vec::len)
        .unwrap_or_default();
    Ok(tutorbot_team_command_with_prelude(
        vec![TutorbotCommandEvent {
            content: format!(
                "Team lead: started `{team_id}` with {worker_count} workers for `{mission}`."
            ),
            metadata: json!({ "team_event": true }),
        }],
        format!(
            "Nano team started: `{}` ({} workers).\nUse `/team status`, `/team log`, `/team stop`.",
            team_id, worker_count
        ),
    ))
}

fn tutorbot_team_status_text(
    state: &AppState,
    bot_id: &str,
    session_key: &str,
) -> Result<TutorbotCommandResponse, ApiError> {
    let Some((run_dir, config)) = latest_tutorbot_team_run(state, bot_id, session_key, true) else {
        update_tutorbot_team_metadata(state, bot_id, session_key, Some(false))?;
        return Ok(tutorbot_team_command_text(
            "No active nano team. Start with `/team <goal>`.",
        ));
    };
    update_tutorbot_team_metadata(state, bot_id, session_key, Some(true))?;
    let members = config["members"]
        .as_array()
        .map(|items| {
            items
                .iter()
                .filter_map(|member| {
                    let name = member["name"].as_str()?;
                    let status = member["status"].as_str().unwrap_or("unknown");
                    Some(format!("{name}={status}"))
                })
                .collect::<Vec<_>>()
                .join(", ")
        })
        .filter(|text| !text.is_empty())
        .unwrap_or_else(|| "(none)".to_string());
    let tasks = tutorbot_team_tasks(&run_dir);
    let total = tasks.len();
    let completed = tasks
        .iter()
        .filter(|task| task["status"].as_str() == Some("completed"))
        .count();
    let active = tasks
        .iter()
        .filter(|task| matches!(task["status"].as_str(), Some("planning" | "in_progress")))
        .count();
    let pending_approval = tasks
        .iter()
        .filter(|task| task["status"].as_str() == Some("awaiting_approval"))
        .count();
    let approvals = tasks
        .iter()
        .filter(|task| task["status"].as_str() == Some("awaiting_approval"))
        .filter_map(|task| task["id"].as_str())
        .take(5)
        .collect::<Vec<_>>();
    let mut lines = vec![
        format!(
            "Team `{}` · {}",
            config["team_id"].as_str().unwrap_or("nano-team"),
            config["status"].as_str().unwrap_or("active")
        ),
        format!(
            "Mission: {}",
            config["mission"].as_str().unwrap_or("(none)")
        ),
        format!("Members: {members}"),
        format!(
            "Tasks: {}/{} completed · {} active · {} awaiting approval",
            completed, total, active, pending_approval
        ),
    ];
    if !approvals.is_empty() {
        lines.push(format!("Approval queue: {}", approvals.join(", ")));
        lines
            .push("Approve with `/team approve <id>` or `/team reject <id> <reason>`.".to_string());
    }
    Ok(tutorbot_team_command_text(lines.join("\n")))
}

fn update_tutorbot_team_task_approval(
    state: &AppState,
    bot_id: &str,
    session_key: &str,
    action: &str,
    task_id: &str,
    detail: Option<&str>,
) -> Result<TutorbotCommandResponse, ApiError> {
    let Some((run_dir, config)) = latest_tutorbot_team_run(state, bot_id, session_key, true) else {
        return Ok(tutorbot_team_command_text("Error: no active team"));
    };
    let mut tasks = tutorbot_team_tasks(&run_dir);
    let Some(index) = tasks
        .iter()
        .position(|task| task["id"].as_str() == Some(task_id))
    else {
        return Ok(tutorbot_team_command_text(format!(
            "Error: task {task_id} not found"
        )));
    };

    let owner = tasks[index]["owner"].as_str().map(ToString::to_string);
    let response = match action {
        "approve" => {
            tasks[index]["status"] = json!("in_progress");
            append_tutorbot_team_event(
                &run_dir,
                "task_approved",
                &format!("Approved task {task_id}"),
                Value::Null,
            )?;
            format!("Updated task {task_id} to in_progress")
        }
        "reject" => {
            let reason = detail.unwrap_or("").trim();
            tasks[index]["status"] = json!("planning");
            tasks[index]["result"] = json!(reason);
            append_tutorbot_team_event(
                &run_dir,
                "task_rejected",
                &format!(
                    "Rejected task {task_id}: {}",
                    reason.chars().take(100).collect::<String>()
                ),
                Value::Null,
            )?;
            format!("Updated task {task_id} to planning")
        }
        "manual" => {
            let instruction = detail.unwrap_or("").trim();
            tasks[index]["status"] = json!("planning");
            tasks[index]["result"] = json!(instruction);
            if let Some(owner) = owner.as_deref().filter(|owner| !owner.is_empty()) {
                fs::create_dir_all(run_dir.join("workers").join(owner))
                    .map_err(|error| tutorbot_team_runtime_error("create worker for", error))?;
                append_tutorbot_team_mail(
                    &run_dir,
                    config["lead"].as_str().unwrap_or("lead"),
                    owner,
                    &format!("Please revise {task_id}: {instruction}"),
                )?;
            }
            append_tutorbot_team_event(
                &run_dir,
                "task_change_requested",
                &format!(
                    "Requested changes on {task_id}: {}",
                    instruction.chars().take(100).collect::<String>()
                ),
                Value::Null,
            )?;
            format!("Requested changes for {task_id}.")
        }
        _ => "Unsupported team action.".to_string(),
    };
    write_tutorbot_team_tasks(&run_dir, &tasks)?;
    update_tutorbot_team_metadata(state, bot_id, session_key, Some(true))?;
    Ok(tutorbot_team_command_text(response))
}

fn tutorbot_pending_approval_ids(run_dir: &FsPath) -> Vec<String> {
    tutorbot_team_tasks(run_dir)
        .into_iter()
        .filter(|task| task["status"].as_str() == Some("awaiting_approval"))
        .filter_map(|task| task["id"].as_str().map(ToString::to_string))
        .collect()
}

fn extract_tutorbot_approval_task_id(text: &str, pending_ids: &[String]) -> Option<String> {
    for token in text.split(|ch: char| !ch.is_ascii_alphanumeric()) {
        let mut chars = token.chars();
        let Some(first) = chars.next() else {
            continue;
        };
        let rest = chars.as_str();
        if !first.eq_ignore_ascii_case(&'t')
            || rest.is_empty()
            || !rest.chars().all(|ch| ch.is_ascii_digit())
        {
            continue;
        }
        if let Some(id) = pending_ids.iter().find(|id| id.eq_ignore_ascii_case(token)) {
            return Some(id.clone());
        }
    }
    (pending_ids.len() == 1).then(|| pending_ids[0].clone())
}

fn tutorbot_text_contains_any(text: &str, keywords: &[&str]) -> bool {
    keywords.iter().any(|keyword| text.contains(keyword))
}

fn clean_tutorbot_approval_feedback(text: &str, task_id: &str) -> String {
    const STRIP_CHARS: &[char] = &[' ', '\t', '\r', '\n', ':', '：', ',', '，', '.', '。'];
    const REMOVED_TOKENS: &[&str] = &[
        "批准", "同意", "通过", "approve", "approved", "拒绝", "驳回", "reject", "decline", "补充",
        "调整", "修改", "指示", "manual", "change",
    ];

    text.split_whitespace()
        .filter(|token| {
            let normalized = token.trim_matches(|ch| STRIP_CHARS.contains(&ch));
            let lowered = normalized.to_lowercase();
            !task_id.eq_ignore_ascii_case(normalized)
                && !REMOVED_TOKENS.iter().any(|removed| lowered == *removed)
        })
        .collect::<Vec<_>>()
        .join(" ")
        .trim_matches(|ch| STRIP_CHARS.contains(&ch))
        .to_string()
}

fn handle_tutorbot_approval_reply(
    state: &AppState,
    bot_id: &str,
    session_key: &str,
    raw: &str,
) -> Result<Option<TutorbotCommandResponse>, ApiError> {
    let Some((run_dir, _config)) = latest_tutorbot_team_run(state, bot_id, session_key, true)
    else {
        return Ok(None);
    };
    let pending_ids = tutorbot_pending_approval_ids(&run_dir);
    if pending_ids.is_empty() {
        return Ok(None);
    }

    let Some(task_id) = extract_tutorbot_approval_task_id(raw, &pending_ids) else {
        return Ok(Some(tutorbot_team_command_text(format!(
            "I found pending approvals but couldn't map your reply to a task. Pending: {}. Please mention the task id in natural language.",
            pending_ids.join(", ")
        ))));
    };

    let lowered = raw.to_lowercase();
    let approve_hit = tutorbot_text_contains_any(
        &lowered,
        &[
            "批准", "同意", "通过", "approve", "approved", "accept", "ok",
        ],
    );
    let reject_hit = tutorbot_text_contains_any(&lowered, &["拒绝", "驳回", "reject", "decline"]);
    let manual_hit = tutorbot_text_contains_any(
        &lowered,
        &["补充", "调整", "修改", "指示", "manual", "change", "revise"],
    );

    if approve_hit && !reject_hit {
        return update_tutorbot_team_task_approval(
            state,
            bot_id,
            session_key,
            "approve",
            &task_id,
            None,
        )
        .map(Some);
    }

    let feedback = clean_tutorbot_approval_feedback(raw, &task_id);
    if reject_hit && !manual_hit {
        if feedback.is_empty() {
            return Ok(Some(tutorbot_team_command_text(
                "I can reject it, but I still need a reason in natural language.",
            )));
        }
        return update_tutorbot_team_task_approval(
            state,
            bot_id,
            session_key,
            "reject",
            &task_id,
            Some(&feedback),
        )
        .map(Some);
    }
    if manual_hit || reject_hit {
        if feedback.is_empty() {
            return Ok(Some(tutorbot_team_command_text(
                "I can send change instructions, but I still need your guidance text.",
            )));
        }
        return update_tutorbot_team_task_approval(
            state,
            bot_id,
            session_key,
            "manual",
            &task_id,
            Some(&feedback),
        )
        .map(Some);
    }

    Ok(Some(tutorbot_team_command_text(
        "I detected approval context but couldn't infer intent. Reply naturally with approve/reject/change + task id.",
    )))
}

fn tutorbot_team_log_text(
    state: &AppState,
    bot_id: &str,
    session_key: &str,
    limit_text: Option<&str>,
) -> TutorbotCommandResponse {
    let limit = limit_text
        .and_then(|text| text.trim().parse::<usize>().ok())
        .unwrap_or(20)
        .clamp(1, 200);
    let Some((run_dir, _config)) = latest_tutorbot_team_run(state, bot_id, session_key, false)
    else {
        return tutorbot_team_command_text("No team logs.");
    };
    let Ok(text) = fs::read_to_string(run_dir.join("events.jsonl")) else {
        return tutorbot_team_command_text("No team logs.");
    };
    let mut lines = text
        .lines()
        .filter_map(|line| serde_json::from_str::<Value>(line).ok())
        .filter_map(|event| {
            let ts = event["ts"].as_str()?.to_string();
            let kind = event["kind"].as_str()?.to_string();
            let message = event["message"].as_str().unwrap_or("").to_string();
            Some(format!("- [{ts}] {kind}: {message}"))
        })
        .collect::<Vec<_>>();
    if lines.is_empty() {
        return tutorbot_team_command_text("No team logs.");
    }
    let start = lines.len().saturating_sub(limit);
    lines = lines[start..].to_vec();
    tutorbot_team_command_text(lines.join("\n"))
}

fn stop_tutorbot_team(
    state: &AppState,
    bot_id: &str,
    session_key: &str,
) -> Result<TutorbotCommandResponse, ApiError> {
    let Some((run_dir, mut config)) = latest_tutorbot_team_run(state, bot_id, session_key, true)
    else {
        update_tutorbot_team_metadata(state, bot_id, session_key, None)?;
        return Ok(tutorbot_team_command_text("No active team."));
    };
    let tasks = tutorbot_team_tasks(&run_dir);
    let all_completed = !tasks.is_empty()
        && tasks
            .iter()
            .all(|task| task["status"].as_str() == Some("completed"));
    config["status"] = json!(if all_completed { "completed" } else { "paused" });
    config["updated_at"] = json!(now_rfc3339());
    if let Some(members) = config["members"].as_array_mut() {
        for member in members {
            member["status"] = json!(if all_completed { "stopped" } else { "idle" });
        }
    }
    write_pretty_json_file(
        &run_dir.join("config.json"),
        &config,
        "write stopped config for",
    )?;
    let stopped_status = config["status"].as_str().unwrap_or("paused").to_string();
    append_tutorbot_team_event(
        &run_dir,
        "team_stopped",
        &format!("Stopped team with status {stopped_status}"),
        json!({ "team_id": config["team_id"], "status": config["status"] }),
    )?;
    update_tutorbot_team_metadata(state, bot_id, session_key, None)?;
    Ok(tutorbot_team_command_text(format!(
        "Team `{}` stopped.",
        config["team_id"].as_str().unwrap_or("nano-team")
    )))
}

async fn handle_tutorbot_slash_command(
    state: &AppState,
    bot_id: &str,
    session_key: &str,
    config: &Value,
    content: &str,
) -> Option<Result<TutorbotCommandResponse, ApiError>> {
    let raw = content.trim();
    let cmd = raw.to_ascii_lowercase();
    if cmd.starts_with("/btw") {
        let arg = raw.get(4..).unwrap_or("").trim();
        return Some(Ok(if arg.is_empty() {
            tutorbot_command_text("Usage: /btw <instruction>")
        } else {
            let task_id = tutorbot_short_task_id();
            spawn_tutorbot_btw_task(state, bot_id, &task_id, arg, config).await;
            tutorbot_command_text(tutorbot_btw_accepted_text(&task_id))
        }));
    }
    if cmd == "/team" {
        return Some(Ok(tutorbot_team_command_text(tutorbot_team_usage_text())));
    }
    if cmd == "/team status" {
        return Some(tutorbot_team_status_text(state, bot_id, session_key));
    }
    if cmd == "/team stop" {
        return Some(stop_tutorbot_team(state, bot_id, session_key));
    }
    if cmd == "/team log" || cmd.starts_with("/team log ") {
        let limit = raw
            .get(9..)
            .map(str::trim)
            .filter(|value| !value.is_empty());
        return Some(Ok(tutorbot_team_log_text(
            state,
            bot_id,
            session_key,
            limit,
        )));
    }
    if cmd == "/team approve" || cmd.starts_with("/team approve ") {
        let task_id = raw.get("/team approve".len()..).unwrap_or("").trim();
        return Some(if task_id.is_empty() {
            Ok(tutorbot_command_text("Usage: /team approve <task_id>"))
        } else {
            update_tutorbot_team_task_approval(state, bot_id, session_key, "approve", task_id, None)
        });
    }
    if cmd == "/team reject" || cmd.starts_with("/team reject ") {
        let rest = raw.get("/team reject".len()..).unwrap_or("").trim();
        let mut parts = rest.splitn(2, |ch: char| ch.is_whitespace());
        let task_id = parts.next().unwrap_or("").trim();
        let reason = parts.next().unwrap_or("").trim();
        return Some(if task_id.is_empty() || reason.is_empty() {
            Ok(tutorbot_command_text(
                "Usage: /team reject <task_id> <reason>",
            ))
        } else {
            update_tutorbot_team_task_approval(
                state,
                bot_id,
                session_key,
                "reject",
                task_id,
                Some(reason),
            )
        });
    }
    if cmd == "/team manual" || cmd.starts_with("/team manual ") {
        let rest = raw.get("/team manual".len()..).unwrap_or("").trim();
        let mut parts = rest.splitn(2, |ch: char| ch.is_whitespace());
        let task_id = parts.next().unwrap_or("").trim();
        let instruction = parts.next().unwrap_or("").trim();
        return Some(if task_id.is_empty() || instruction.is_empty() {
            Ok(tutorbot_command_text(
                "Usage: /team manual <task_id> <instruction>",
            ))
        } else {
            update_tutorbot_team_task_approval(
                state,
                bot_id,
                session_key,
                "manual",
                task_id,
                Some(instruction),
            )
        });
    }
    if cmd.starts_with("/team ") || cmd.starts_with("/teams ") {
        let offset = if cmd.starts_with("/teams ") { 7 } else { 6 };
        let mission = raw.get(offset..).unwrap_or("").trim();
        return Some(start_tutorbot_team(state, bot_id, session_key, config, mission).await);
    }
    match cmd.as_str() {
        "/help" => Some(Ok(tutorbot_command_text(tutorbot_help_text()))),
        "/new" => Some(
            match archive_tutorbot_session_for_new(state, bot_id, session_key) {
                Ok(()) => reset_tutorbot_session(state, bot_id, session_key)
                    .map(|()| tutorbot_command_text("New session started.")),
                Err(_) => Ok(tutorbot_command_text(
                    "Memory archival failed, session not cleared. Please try again.",
                )),
            },
        ),
        "/stop" => {
            let stopped = state.tutorbot_runtime.cancel_btw_tasks(bot_id).await;
            Some(Ok(tutorbot_command_text(if stopped == 0 {
                "No active task to stop.".to_string()
            } else {
                format!("Stopped {stopped} task(s).")
            })))
        }
        "/restart" => Some(Ok(tutorbot_command_text("Restarting..."))),
        _ => None,
    }
}

async fn handle_tutorbot_socket(mut socket: WebSocket, state: AppState, bot_id: String) {
    let Some(bot_id) = safe_storage_component(&bot_id) else {
        let _ = socket
            .send(Message::Text(
                json!({"type": "error", "content": "Invalid bot id"})
                    .to_string()
                    .into(),
            ))
            .await;
        let _ = socket.send(Message::Close(None)).await;
        return;
    };

    let Some(mut config) = read_tutorbot_config(&state, &bot_id) else {
        let _ = socket
            .send(Message::Text(
                json!({"type": "error", "content": "Bot not found"})
                    .to_string()
                    .into(),
            ))
            .await;
        let _ = socket.send(Message::Close(None)).await;
        return;
    };

    if !config["running"].as_bool().unwrap_or(false) {
        config["running"] = json!(true);
        config["started_at"] = json!(now_rfc3339());
        let _ = write_tutorbot_config(&state, &bot_id, &config);
    }

    let mut notification_rx = state.tutorbot_runtime.subscribe(&bot_id).await;
    loop {
        let message = tokio::select! {
            notification = notification_rx.recv() => {
                match notification {
                    Ok(event) => {
                        if socket
                            .send(Message::Text(event.to_string().into()))
                            .await
                            .is_err()
                        {
                            break;
                        }
                        continue;
                    }
                    Err(broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(broadcast::error::RecvError::Closed) => continue,
                }
            }
            message = socket.recv() => message,
        };
        let Some(Ok(message)) = message else {
            break;
        };
        let Message::Text(text) = message else {
            if matches!(message, Message::Close(_)) {
                break;
            }
            continue;
        };
        let Ok(payload) = serde_json::from_str::<Value>(&text) else {
            let _ = socket
                .send(Message::Text(
                    json!({"type": "error", "content": "Invalid JSON"})
                        .to_string()
                        .into(),
                ))
                .await;
            continue;
        };
        let content = payload["content"].as_str().unwrap_or("").trim();
        if content.is_empty() {
            continue;
        }
        let session_key = tutorbot_canonical_session_key(&bot_id);
        let command_result =
            handle_tutorbot_slash_command(&state, &bot_id, &session_key, &config, content)
                .await
                .or_else(|| {
                    if content.starts_with('/') {
                        return None;
                    }
                    match handle_tutorbot_approval_reply(&state, &bot_id, &session_key, content) {
                        Ok(Some(response)) => Some(Ok(response)),
                        Ok(None) => None,
                        Err(error) => Some(Err(error)),
                    }
                });
        if let Some(command_result) = command_result {
            match command_result {
                Ok(response) => {
                    for event in response.prelude {
                        if socket
                            .send(Message::Text(
                                json!({
                                    "type": "content",
                                    "content": event.content,
                                    "metadata": event.metadata
                                })
                                .to_string()
                                .into(),
                            ))
                            .await
                            .is_err()
                        {
                            break;
                        }
                    }
                    if socket
                        .send(Message::Text(
                            json!({
                                "type": "content",
                                "content": response.content,
                                "metadata": response.metadata
                            })
                            .to_string()
                            .into(),
                        ))
                        .await
                        .is_err()
                    {
                        break;
                    }
                    if socket
                        .send(Message::Text(json!({"type": "done"}).to_string().into()))
                        .await
                        .is_err()
                    {
                        break;
                    }
                }
                Err(error) => {
                    let detail = error.1.0["detail"]
                        .as_str()
                        .unwrap_or("TutorBot command failed");
                    if socket
                        .send(Message::Text(
                            json!({"type": "error", "content": detail})
                                .to_string()
                                .into(),
                        ))
                        .await
                        .is_err()
                    {
                        break;
                    }
                }
            }
            continue;
        }
        let _ = append_tutorbot_history(&state, &bot_id, &session_key, "user", content);
        let _ = socket
            .send(Message::Text(
                json!({"type": "thinking", "content": "TutorBot is reading the local profile and conversation history."})
                    .to_string()
                    .into(),
            ))
            .await;
        match tutorbot_chat_response(&state, &bot_id, &config, &payload, content).await {
            Ok(result) => {
                let _ = append_tutorbot_history(
                    &state,
                    &bot_id,
                    &session_key,
                    "assistant",
                    &result.content,
                );
                if socket
                    .send(Message::Text(
                        json!({
                            "type": "content",
                            "content": result.content,
                            "metadata": result.metadata
                        })
                        .to_string()
                        .into(),
                    ))
                    .await
                    .is_err()
                {
                    break;
                }
                if socket
                    .send(Message::Text(json!({"type": "done"}).to_string().into()))
                    .await
                    .is_err()
                {
                    break;
                }
            }
            Err(error) => {
                if socket
                    .send(Message::Text(
                        json!({"type": "error", "content": error})
                            .to_string()
                            .into(),
                    ))
                    .await
                    .is_err()
                {
                    break;
                }
            }
        }
    }
}

#[derive(Debug, Clone)]
struct TutorBotTurnResult {
    content: String,
    metadata: Value,
}

async fn tutorbot_chat_response(
    state: &AppState,
    bot_id: &str,
    config: &Value,
    payload: &Value,
    content: &str,
) -> Result<TutorBotTurnResult, String> {
    let selection_value = payload
        .get("llm_selection")
        .filter(|value| !value.is_null())
        .unwrap_or(&config["llm_selection"]);
    let selection = active_chat_selection(&load_settings_catalog(state), selection_value)?;
    let Some(selection) = selection else {
        return Ok(TutorBotTurnResult {
            content: tutorbot_fallback_response(bot_id, config, content),
            metadata: json!({ "provider": "deterministic", "model": "deterministic-agent-loop" }),
        });
    };

    let enabled_tools = requested_tutorbot_chat_tool_names(payload, config);
    let knowledge_bases = as_string_array(&payload["knowledge_bases"]);
    let mcp_tools = discover_tutorbot_mcp_tools(config, &enabled_tools).await;
    let mut metadata = json!({
        "profile_id": selection.profile_id.as_str(),
        "model_id": selection.model_id.as_str(),
        "model": selection.model.as_str(),
        "provider": selection.binding.as_str()
    });
    let mut additional_messages = Vec::new();
    let mut raw_tool_results = Vec::new();
    let mut total_tool_calls = 0usize;
    let mut answer = None::<String>;

    for _ in 0..MAX_TUTORBOT_TOOL_ITERATIONS {
        let body = tutorbot_chat_completion_body(TutorbotChatCompletionRequest {
            selection: &selection,
            state,
            bot_id,
            config,
            content,
            enabled_tools: &enabled_tools,
            mcp_tools: &mcp_tools,
            additional_messages: &additional_messages,
        });
        let response = call_chat_completion_provider(&selection, body).await?;
        if response.tool_calls.is_empty() {
            merge_chat_provider_response_metadata(&mut metadata, &response);
            answer = Some(response.content.clone().ok_or_else(|| {
                "TutorBot LLM response did not include assistant content".to_string()
            })?);
            break;
        }

        let tool_calls = normalized_chat_tool_calls(&response.tool_calls);
        let (tool_messages, _trace_results, call_tool_results) = execute_chat_provider_tool_calls(
            state,
            &enabled_tools,
            &knowledge_bases,
            content,
            &tool_calls,
            &mcp_tools,
            None,
        )
        .await;
        total_tool_calls += tool_calls.len();
        raw_tool_results.extend(call_tool_results);
        additional_messages.push(assistant_tool_call_message(&response, &tool_calls));
        additional_messages.extend(tool_messages);
    }

    if total_tool_calls > 0
        && let Some(object) = metadata.as_object_mut()
    {
        object.insert("tool_calls".to_string(), json!(total_tool_calls));
        object.insert("tool_results".to_string(), Value::Array(raw_tool_results));
    }

    let answer = answer.unwrap_or_else(|| {
        if let Some(object) = metadata.as_object_mut() {
            object.insert("finish_reason".to_string(), json!("max_tool_iterations"));
        }
        format!(
            "I reached the maximum number of tool call iterations ({MAX_TUTORBOT_TOOL_ITERATIONS}) without completing the task. You can try breaking the task into smaller steps."
        )
    });

    Ok(TutorBotTurnResult {
        content: answer,
        metadata,
    })
}

struct TutorbotChatCompletionRequest<'a> {
    selection: &'a ChatRuntimeSelection,
    state: &'a AppState,
    bot_id: &'a str,
    config: &'a Value,
    content: &'a str,
    enabled_tools: &'a [String],
    mcp_tools: &'a [TutorbotMcpToolDefinition],
    additional_messages: &'a [Value],
}

fn tutorbot_chat_completion_body(request: TutorbotChatCompletionRequest<'_>) -> Value {
    let mut messages = vec![json!({
        "role": "system",
        "content": tutorbot_system_prompt(request.state, request.bot_id, request.config)
    })];
    messages.extend(tutorbot_provider_history_messages(
        request.state,
        request.bot_id,
        request.content,
        12,
    ));
    messages.push(json!({
        "role": "user",
        "content": request.content
    }));
    messages.extend(request.additional_messages.iter().cloned());
    let mut body = json!({
        "model": request.selection.model.as_str(),
        "messages": messages,
        "stream": false
    });
    let tool_definitions = openai_chat_tool_definitions_with_mcp(
        request.selection,
        request.enabled_tools,
        request.mcp_tools,
    );
    if !tool_definitions.is_empty() {
        body["tools"] = Value::Array(tool_definitions);
        body["tool_choice"] = json!("auto");
    }
    body
}

fn tutorbot_system_prompt(state: &AppState, bot_id: &str, config: &Value) -> String {
    let name = config["name"].as_str().unwrap_or(bot_id);
    let mut prompt = format!(
        "You are {name}, a Socartes TutorBot. Answer directly, use selected course evidence when relevant, and avoid inventing facts outside the available context."
    );
    if let Some(description) = config["description"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        prompt.push_str("\n\nDescription:\n");
        prompt.push_str(description);
    }
    if let Some(persona) = config["persona"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        prompt.push_str("\n\nSoul:\n");
        prompt.push_str(persona);
    }
    for filename in ["USER.md", "TOOLS.md", "AGENTS.md"] {
        let Some(text) = read_tutorbot_workspace_file(state, bot_id, filename)
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty())
        else {
            continue;
        };
        prompt.push_str("\n\n");
        prompt.push_str(filename);
        prompt.push_str(":\n");
        prompt.push_str(&truncate_for_prompt(&text, 1800));
    }
    prompt
}

fn tutorbot_provider_history_messages(
    state: &AppState,
    bot_id: &str,
    current_content: &str,
    limit: usize,
) -> Vec<Value> {
    let mut history = tutorbot_history_messages(state, bot_id, limit)
        .into_iter()
        .filter_map(|message| {
            let role = message["role"].as_str()?;
            if role != "user" && role != "assistant" {
                return None;
            }
            let content = message["content"].as_str()?.trim();
            if content.is_empty() {
                return None;
            }
            Some(json!({
                "role": role,
                "content": truncate_for_prompt(content, 6000)
            }))
        })
        .collect::<Vec<_>>();
    if history.last().is_some_and(|message| {
        message["role"] == "user"
            && message["content"].as_str().unwrap_or("").trim() == current_content.trim()
    }) {
        history.pop();
    }
    history
}

fn tutorbot_fallback_response(bot_id: &str, config: &Value, content: &str) -> String {
    let name = config["name"].as_str().unwrap_or(bot_id);
    let persona = config["persona"].as_str().unwrap_or("").trim();
    let persona_clause = if persona.is_empty() {
        "using the default Socartes tutor profile".to_string()
    } else {
        format!("using this profile: {}", compact_excerpt(persona, 220))
    };
    format!(
        "{name} received: \"{content}\". I am responding through the Rust TutorBot compatibility runtime, {persona_clause}."
    )
}

fn now_rfc3339() -> String {
    Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true)
}

fn current_epoch_millis() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or_default()
}

fn knowledge_base_dir(state: &AppState, name: &str) -> PathBuf {
    let component = safe_storage_component(name).unwrap_or_else(|| "invalid".to_string());
    let modern = state.knowledge_root.join("bases").join(&component);
    if modern.is_dir() {
        return modern;
    }
    let legacy = state.knowledge_root.join(&component);
    if legacy.is_dir() {
        return legacy;
    }
    modern
}

fn knowledge_files_dir(state: &AppState, name: &str) -> PathBuf {
    let base_dir = knowledge_base_dir(state, name);
    knowledge_files_dir_at_dir(&base_dir)
}

fn knowledge_files_dir_at_dir(base_dir: &FsPath) -> PathBuf {
    let modern = base_dir.join("files");
    if modern.is_dir() {
        return modern;
    }
    let legacy = base_dir.join("raw");
    if legacy.is_dir() {
        return legacy;
    }
    modern
}

fn knowledge_metadata_path(state: &AppState, name: &str) -> PathBuf {
    knowledge_base_dir(state, name).join("metadata.json")
}

fn default_knowledge_path(state: &AppState) -> PathBuf {
    state.knowledge_root.join("default.txt")
}

fn knowledge_config_path(state: &AppState) -> PathBuf {
    state.knowledge_root.join("kb_config.json")
}

fn knowledge_progress_path(state: &AppState, name: &str) -> PathBuf {
    let base_dir = knowledge_base_dir(state, name);
    let modern = base_dir.join("progress.json");
    if modern.exists() {
        return modern;
    }
    let legacy = base_dir.join(".progress.json");
    if legacy.exists() {
        return legacy;
    }
    modern
}

fn linked_knowledge_folders_path(state: &AppState, name: &str) -> PathBuf {
    knowledge_base_dir(state, name).join("linked_folders.json")
}

fn read_default_knowledge_base(state: &AppState) -> String {
    fs::read_to_string(default_knowledge_path(state))
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| knowledge_base_exists(state, value))
        .or_else(|| {
            fs::read_to_string(knowledge_config_path(state))
                .ok()
                .and_then(|text| serde_json::from_str::<Value>(&text).ok())
                .and_then(|store| {
                    store["defaults"]["default_kb"]
                        .as_str()
                        .map(str::trim)
                        .filter(|value| !value.is_empty())
                        .map(ToString::to_string)
                })
                .filter(|value| knowledge_base_exists(state, value))
        })
        .unwrap_or_else(|| BUILTIN_KNOWLEDGE_BASE.to_string())
}

fn default_knowledge_config_store(state: &AppState) -> Value {
    json!({
        "defaults": {
            "default_kb": read_default_knowledge_base(state),
            "rag_provider": DEFAULT_RAG_PROVIDER,
            "search_mode": "hybrid"
        },
        "knowledge_bases": {}
    })
}

fn load_knowledge_config_store(state: &AppState) -> Value {
    let mut store = fs::read_to_string(knowledge_config_path(state))
        .ok()
        .and_then(|text| serde_json::from_str::<Value>(&text).ok())
        .filter(|value| value.is_object())
        .unwrap_or_else(|| default_knowledge_config_store(state));
    if !store["defaults"].is_object() {
        store["defaults"] = json!({});
    }
    if !store["knowledge_bases"].is_object() {
        store["knowledge_bases"] = json!({});
    }
    store["defaults"]["default_kb"] = json!(read_default_knowledge_base(state));
    store["defaults"]["rag_provider"] = json!(DEFAULT_RAG_PROVIDER);
    if store["defaults"]["search_mode"]
        .as_str()
        .unwrap_or("")
        .is_empty()
    {
        store["defaults"]["search_mode"] = json!("hybrid");
    }
    store
}

fn write_knowledge_config_store(state: &AppState, store: &Value) -> Result<(), ApiError> {
    fs::create_dir_all(&*state.knowledge_root).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to create knowledge config directory: {error}"),
        )
    })?;
    let bytes = serde_json::to_vec_pretty(store).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to serialize knowledge config: {error}"),
        )
    })?;
    fs::write(knowledge_config_path(state), bytes).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to write knowledge config: {error}"),
        )
    })
}

fn default_knowledge_base_config(state: &AppState, name: &str) -> Value {
    json!({
        "default_kb": read_default_knowledge_base(state),
        "rag_provider": DEFAULT_RAG_PROVIDER,
        "search_mode": "hybrid",
        "needs_reindex": false,
        "path": name,
        "description": format!("Knowledge base: {name}")
    })
}

fn merged_knowledge_config(state: &AppState, name: &str) -> Value {
    let store = load_knowledge_config_store(state);
    let mut config = default_knowledge_base_config(state, name);
    if let Some(stored) = store["knowledge_bases"]
        .get(name)
        .and_then(Value::as_object)
    {
        for (key, value) in stored {
            config[key] = value.clone();
        }
    }
    config["default_kb"] = json!(read_default_knowledge_base(state));
    config["rag_provider"] = json!(DEFAULT_RAG_PROVIDER);
    if config["search_mode"].as_str().unwrap_or("").is_empty() {
        config["search_mode"] = json!("hybrid");
    }
    config["needs_reindex"] = json!(config["needs_reindex"].as_bool().unwrap_or(false));
    config
}

fn write_knowledge_progress(
    state: &AppState,
    name: &str,
    progress: &Value,
) -> Result<(), ApiError> {
    let dir = knowledge_base_dir(state, name);
    fs::create_dir_all(&dir).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to create knowledge base directory: {error}"),
        )
    })?;
    let bytes = serde_json::to_vec_pretty(progress).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to serialize progress: {error}"),
        )
    })?;
    fs::write(knowledge_progress_path(state, name), bytes).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to write progress: {error}"),
        )
    })
}

fn load_linked_knowledge_folders(state: &AppState, name: &str) -> Vec<Value> {
    fs::read_to_string(linked_knowledge_folders_path(state, name))
        .ok()
        .and_then(|text| serde_json::from_str::<Value>(&text).ok())
        .and_then(|value| value.as_array().cloned())
        .unwrap_or_default()
}

fn write_linked_knowledge_folders(
    state: &AppState,
    name: &str,
    folders: &[Value],
) -> Result<(), ApiError> {
    let dir = knowledge_base_dir(state, name);
    fs::create_dir_all(&dir).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to create knowledge base directory: {error}"),
        )
    })?;
    let bytes = serde_json::to_vec_pretty(folders).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to serialize linked folders: {error}"),
        )
    })?;
    fs::write(linked_knowledge_folders_path(state, name), bytes).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to write linked folders: {error}"),
        )
    })
}

fn linked_folder_changes(folder: &Value, source_dir: &FsPath) -> (Vec<PathBuf>, Vec<PathBuf>) {
    let synced_files = folder["synced_files"].as_object();
    let mut new_files = Vec::new();
    let mut modified_files = Vec::new();
    for path in supported_files_in_dir(source_dir) {
        let key = path.to_string_lossy();
        let current_modified = file_modified_rfc3339(&path);
        match synced_files.and_then(|files| files.get(key.as_ref()).and_then(Value::as_str)) {
            Some(previous_modified) if current_modified.as_deref() == Some(previous_modified) => {}
            Some(_) => modified_files.push(path),
            None => new_files.push(path),
        }
    }
    (new_files, modified_files)
}

fn update_linked_folder_sync_state(
    state: &AppState,
    name: &str,
    folders: &mut [Value],
    folder_index: usize,
    synced_paths: &[PathBuf],
) -> Result<(), ApiError> {
    let Some(folder) = folders.get_mut(folder_index).and_then(Value::as_object_mut) else {
        return Err(api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "Linked folder metadata is invalid",
        ));
    };
    let mut file_states = folder
        .get("synced_files")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_else(Map::new);
    for path in synced_paths {
        if let Some(modified_at) = file_modified_rfc3339(path) {
            file_states.insert(path.to_string_lossy().to_string(), json!(modified_at));
        }
    }
    folder.insert("last_sync".to_string(), json!(now_rfc3339()));
    folder.insert("file_count".to_string(), json!(file_states.len()));
    folder.insert("synced_files".to_string(), Value::Object(file_states));
    write_linked_knowledge_folders(state, name, folders)
}

fn file_modified_rfc3339(path: &FsPath) -> Option<String> {
    let modified = path.metadata().ok()?.modified().ok()?;
    let datetime: chrono::DateTime<Utc> = modified.into();
    Some(datetime.to_rfc3339_opts(SecondsFormat::Micros, true))
}

fn expand_user_path(path: &str) -> PathBuf {
    if path == "~" {
        return env::var_os("HOME")
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from(path));
    }
    if let Some(rest) = path.strip_prefix("~/") {
        return env::var_os("HOME")
            .map(PathBuf::from)
            .map(|home| home.join(rest))
            .unwrap_or_else(|| PathBuf::from(path));
    }
    PathBuf::from(path)
}

fn count_supported_files_in_dir(path: &FsPath) -> usize {
    supported_files_in_dir(path).len()
}

fn supported_files_in_dir(path: &FsPath) -> Vec<PathBuf> {
    let mut files = Vec::new();
    collect_supported_files_in_dir(path, &mut files);
    files.sort_by(|left, right| left.to_string_lossy().cmp(&right.to_string_lossy()));
    files
}

fn collect_supported_files_in_dir(path: &FsPath, files: &mut Vec<PathBuf>) {
    let Ok(entries) = fs::read_dir(path) else {
        return;
    };
    for entry in entries.filter_map(Result::ok) {
        let path = entry.path();
        if path.is_dir() {
            collect_supported_files_in_dir(&path, files);
            continue;
        }
        if !path.is_file() {
            continue;
        }
        let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
            continue;
        };
        if is_supported_knowledge_file(name) {
            files.push(path);
        }
    }
}

fn knowledge_base_exists(state: &AppState, name: &str) -> bool {
    name == BUILTIN_KNOWLEDGE_BASE || knowledge_base_dir(state, name).is_dir()
}

fn local_knowledge_base_names(state: &AppState) -> Vec<String> {
    let mut names = BTreeSet::new();
    names.extend(directory_child_names(&state.knowledge_root.join("bases")));
    for name in directory_child_names(&state.knowledge_root) {
        if name == "bases" {
            continue;
        }
        let candidate = state.knowledge_root.join(&name);
        if candidate.join("raw").is_dir()
            || candidate.join("files").is_dir()
            || candidate.join("metadata.json").is_file()
            || candidate.join("version-1").is_dir()
        {
            names.insert(name);
        }
    }
    names.into_iter().collect()
}

fn now_label() -> String {
    format!("{:.0}", now_seconds())
}

fn knowledge_task_id(task_type: &str) -> String {
    let timestamp = Utc::now().format("%Y%m%d_%H%M%S");
    let suffix = format!("{:08x}", unique_id() & 0xffff_ffff);
    format!("{task_type}_{timestamp}_{suffix}")
}

fn knowledge_base_summaries(state: &AppState) -> Vec<Value> {
    let default_name = read_default_knowledge_base(state);
    let mut summaries = vec![builtin_knowledge_summary(&default_name)];

    for name in local_knowledge_base_names(state) {
        summaries.push(local_knowledge_summary(state, &name, &default_name));
    }

    summaries
}

fn annotate_knowledge_summary(mut summary: Value, access: &KnowledgeAccess) -> Value {
    summary["id"] = json!(access.id());
    summary["source"] = json!(access.source());
    summary["assigned"] = json!(access.assigned());
    summary["read_only"] = json!(access.read_only());
    if access.assigned() {
        summary
            .as_object_mut()
            .expect("summary object")
            .remove("path");
        summary["provenance_label"] = json!("Assigned by admin");
    }
    summary
}

fn knowledge_summary_for_access(state: &AppState, access: &KnowledgeAccess) -> Value {
    let default_name = read_default_knowledge_base(state);
    let summary = match access {
        KnowledgeAccess::Builtin => builtin_knowledge_summary(&default_name),
        KnowledgeAccess::Admin { name, .. } => local_knowledge_summary(state, name, &default_name),
        KnowledgeAccess::User { name, user_id } => local_knowledge_summary_at_dir(
            state,
            name,
            &default_name,
            &user_knowledge_base_dir(state, user_id, name),
        ),
    };
    annotate_knowledge_summary(summary, access)
}

fn scoped_knowledge_base_summaries(state: &AppState, payload: &AuthTokenPayload) -> Vec<Value> {
    if payload.role == "admin" {
        return knowledge_base_summaries(state)
            .into_iter()
            .map(|summary| {
                let name = summary["name"].as_str().unwrap_or("").to_string();
                let access = if name == BUILTIN_KNOWLEDGE_BASE {
                    KnowledgeAccess::Builtin
                } else {
                    KnowledgeAccess::Admin {
                        name,
                        assigned: false,
                    }
                };
                annotate_knowledge_summary(summary, &access)
            })
            .collect();
    }

    let mut summaries = Vec::new();
    let mut seen = HashSet::new();
    for name in user_knowledge_base_names(state, &payload.user_id) {
        let access = KnowledgeAccess::User {
            name: name.clone(),
            user_id: payload.user_id.clone(),
        };
        seen.insert(access.id());
        summaries.push(knowledge_summary_for_access(state, &access));
    }

    let grant = load_settings_grant(state, &payload.user_id);
    let admin_names = admin_knowledge_base_names(state)
        .into_iter()
        .collect::<HashSet<_>>();
    let mut granted = grant["knowledge_bases"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|item| {
            knowledge_grant_name(item).map(|name| {
                (
                    name,
                    item["needs_admin_reindex"].as_bool().unwrap_or(false),
                    item["embedding_signature"]
                        .as_str()
                        .unwrap_or("")
                        .to_string(),
                )
            })
        })
        .collect::<Vec<_>>();
    granted.sort_by(|left, right| left.0.cmp(&right.0));
    for (name, needs_admin_reindex, embedding_signature) in granted {
        let access = KnowledgeAccess::Admin {
            name: name.clone(),
            assigned: true,
        };
        if !seen.insert(access.id()) {
            continue;
        }
        if admin_names.contains(&name) {
            let mut summary = knowledge_summary_for_access(state, &access);
            summary["available"] = json!(true);
            summary["needs_admin_reindex"] = json!(needs_admin_reindex);
            summary["embedding_signature"] = json!(embedding_signature);
            summaries.push(summary);
        } else {
            summaries.push(json!({
                "id": access.id(),
                "name": name,
                "source": "admin",
                "assigned": true,
                "read_only": true,
                "available": false,
                "status": "unavailable",
                "provenance_label": "Assigned by admin",
                "needs_admin_reindex": needs_admin_reindex,
                "embedding_signature": embedding_signature
            }));
        }
    }
    summaries
}

fn builtin_knowledge_summary(default_name: &str) -> Value {
    json!({
        "name": BUILTIN_KNOWLEDGE_BASE,
        "is_default": default_name == BUILTIN_KNOWLEDGE_BASE,
        "status": "ready",
        "path": "builtin://socartes-rust-rag",
        "metadata": {
            "description": "Built-in Socartes Rust RAG notes for local frontend smoke tests.",
            "rag_provider": DEFAULT_RAG_PROVIDER,
            "last_updated": "builtin"
        },
        "statistics": {
            "raw_documents": builtin_knowledge_file_entries().len(),
            "images": 0,
            "content_lists": 0,
            "chunks": knowledge_base().len(),
            "rag_provider": DEFAULT_RAG_PROVIDER,
            "rag_initialized": true,
            "needs_reindex": false,
            "status": "ready",
            "active_match": true,
            "index_versions": [
                {
                    "signature": "socartes-rust-builtin",
                    "model": "deterministic-agent-loop",
                    "dimension": 0,
                    "binding": "builtin",
                    "created_at": "builtin",
                    "ready": true,
                    "legacy": false
                }
            ],
            "active_signature": "socartes-rust-builtin"
        }
    })
}

fn local_knowledge_summary(state: &AppState, name: &str, default_name: &str) -> Value {
    local_knowledge_summary_at_dir(state, name, default_name, &knowledge_base_dir(state, name))
}

fn local_knowledge_summary_at_dir(
    state: &AppState,
    name: &str,
    default_name: &str,
    kb_dir: &FsPath,
) -> Value {
    let files = knowledge_files_at_dir(&knowledge_files_dir_at_dir(kb_dir)).unwrap_or_default();
    let metadata = read_knowledge_metadata_at_dir(kb_dir).unwrap_or_else(|| {
        json!({
            "created_at": now_label(),
            "last_updated": now_label(),
            "rag_provider": DEFAULT_RAG_PROVIDER,
            "needs_reindex": true
        })
    });
    let index_versions = knowledge_index_versions(kb_dir, &metadata);
    let active_signature = active_knowledge_signature(state);
    let active_match = index_versions.iter().any(|version| {
        version["signature"].as_str() == Some(active_signature.as_str())
            && version["ready"].as_bool().unwrap_or(false)
    });
    let rag_initialized = index_versions
        .iter()
        .any(|version| version["ready"].as_bool().unwrap_or(false));
    let needs_reindex =
        metadata["needs_reindex"].as_bool().unwrap_or(!active_match) && !active_match;
    let status = if needs_reindex {
        "needs_reindex"
    } else if rag_initialized {
        "ready"
    } else {
        "unknown"
    };
    json!({
        "name": name,
        "is_default": default_name == name,
        "status": status,
        "path": kb_dir.to_string_lossy(),
        "metadata": metadata,
        "statistics": {
            "raw_documents": files.len(),
            "images": 0,
            "content_lists": 0,
            "rag_provider": metadata["rag_provider"].as_str().unwrap_or(DEFAULT_RAG_PROVIDER),
            "rag_initialized": rag_initialized,
            "needs_reindex": needs_reindex,
            "status": status,
            "active_match": active_match,
            "index_versions": index_versions,
            "active_signature": active_signature
        }
    })
}

fn knowledge_embedding_signature(
    binding: &str,
    model: &str,
    dimension: i64,
    base_url: &str,
    api_version: &str,
) -> String {
    let canonical = json!({
        "api_version": api_version,
        "base_url": base_url,
        "binding": binding,
        "dimension": dimension,
        "model": model
    });
    let serialized = serde_json::to_string(&canonical).unwrap_or_default();
    let digest = Sha256::digest(serialized.as_bytes());
    format!("{digest:x}").chars().take(16).collect()
}

fn fallback_knowledge_embedding_config() -> KnowledgeEmbeddingConfig {
    let signature = knowledge_embedding_signature(
        RUST_EMBEDDING_BINDING,
        RUST_EMBEDDING_MODEL,
        RUST_EMBEDDING_DIMENSION,
        RUST_EMBEDDING_BASE_URL,
        RUST_EMBEDDING_API_VERSION,
    );
    KnowledgeEmbeddingConfig {
        binding: RUST_EMBEDDING_BINDING.to_string(),
        model: RUST_EMBEDDING_MODEL.to_string(),
        dimension: RUST_EMBEDDING_DIMENSION,
        base_url: RUST_EMBEDDING_BASE_URL.to_string(),
        api_version: RUST_EMBEDDING_API_VERSION.to_string(),
        signature,
        selection: None,
    }
}

fn active_knowledge_embedding_config(state: &AppState) -> KnowledgeEmbeddingConfig {
    let Some(catalog) = read_settings_json(state, "catalog.json") else {
        return fallback_knowledge_embedding_config();
    };
    let Ok(selection) = active_embedding_selection(&catalog) else {
        return fallback_knowledge_embedding_config();
    };
    let dimension = selection.dimension.unwrap_or_default();
    let signature = knowledge_embedding_signature(
        &selection.binding,
        &selection.model,
        dimension,
        &selection.base_url,
        &selection.api_version,
    );
    KnowledgeEmbeddingConfig {
        binding: selection.binding.clone(),
        model: selection.model.clone(),
        dimension,
        base_url: selection.base_url.clone(),
        api_version: selection.api_version.clone(),
        signature,
        selection: Some(selection),
    }
}

fn active_knowledge_signature(state: &AppState) -> String {
    active_knowledge_embedding_config(state).signature
}

fn knowledge_index_versions(kb_dir: &FsPath, metadata: &Value) -> Vec<Value> {
    let mut versions = Vec::new();
    if let Ok(entries) = fs::read_dir(kb_dir) {
        for entry in entries.filter_map(Result::ok) {
            let path = entry.path();
            if !path.is_dir() {
                continue;
            }
            let Some(version_name) = path.file_name().and_then(|value| value.to_str()) else {
                continue;
            };
            if !version_name.starts_with("version-") {
                continue;
            }
            let Ok(text) = fs::read_to_string(path.join("meta.json")) else {
                continue;
            };
            let Ok(mut version) = serde_json::from_str::<Value>(&text) else {
                continue;
            };
            version["version"] = json!(
                version["version"]
                    .as_str()
                    .unwrap_or(version_name)
                    .to_string()
            );
            version["layout"] = json!(version["layout"].as_str().unwrap_or("flat"));
            version["ready"] = json!(version["ready"].as_bool().unwrap_or(true));
            version["legacy"] = json!(version["legacy"].as_bool().unwrap_or(false));
            version["storage_path"] = json!(path.to_string_lossy());
            version["version_path"] = json!(path.to_string_lossy());
            versions.push(version);
        }
    }
    versions.sort_by(|left, right| {
        version_number(left)
            .cmp(&version_number(right))
            .then_with(|| left["signature"].as_str().cmp(&right["signature"].as_str()))
    });
    if versions.is_empty() {
        metadata["index_versions"]
            .as_array()
            .cloned()
            .unwrap_or_default()
    } else {
        versions
    }
}

fn version_number(version: &Value) -> usize {
    version["version"]
        .as_str()
        .and_then(|value| value.strip_prefix("version-"))
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or_default()
}

fn find_active_index_version<'a>(state: &AppState, versions: &'a [Value]) -> Option<&'a Value> {
    let signature = active_knowledge_signature(state);
    versions.iter().find(|version| {
        version["signature"].as_str() == Some(signature.as_str())
            && version["ready"].as_bool().unwrap_or(false)
    })
}

fn next_knowledge_version_name(versions: &[Value]) -> String {
    let next = versions
        .iter()
        .filter_map(|version| version["version"].as_str())
        .filter_map(|version| version.strip_prefix("version-"))
        .filter_map(|suffix| suffix.parse::<usize>().ok())
        .max()
        .unwrap_or_default()
        + 1;
    format!("version-{next}")
}

fn build_active_index_version(state: &AppState, versions: &[Value]) -> Value {
    let embedding = active_knowledge_embedding_config(state);
    json!({
        "version": next_knowledge_version_name(versions),
        "signature": embedding.signature,
        "binding": embedding.binding,
        "model": embedding.model,
        "dimension": embedding.dimension,
        "base_url": embedding.base_url,
        "api_version": embedding.api_version,
        "layout": "flat",
        "created_at": Utc::now().to_rfc3339_opts(SecondsFormat::Millis, true),
        "ready": true,
        "legacy": false
    })
}

async fn write_active_knowledge_index_version(
    state: &AppState,
    name: &str,
    versions: &[Value],
) -> Result<Value, ApiError> {
    let mut version = build_active_index_version(state, versions);
    let version_name = version["version"]
        .as_str()
        .unwrap_or("version-1")
        .to_string();
    let version_dir = knowledge_base_dir(state, name).join(&version_name);
    fs::create_dir_all(&version_dir).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to create index version directory: {error}"),
        )
    })?;
    version["storage_path"] = json!(version_dir.to_string_lossy());
    version["version_path"] = json!(version_dir.to_string_lossy());

    let mut chunks = build_knowledge_index_chunks(state, name)?;
    let texts = chunks
        .iter()
        .map(|chunk| chunk["content"].as_str().unwrap_or_default().to_string())
        .collect::<Vec<_>>();
    let embeddings = embed_knowledge_texts(state, &texts).await?;
    attach_embeddings_to_chunks(&mut chunks, embeddings)?;
    write_knowledge_index_files(&version_dir, &version["signature"], chunks)?;

    let bytes = serde_json::to_vec_pretty(&version).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to serialize index version metadata: {error}"),
        )
    })?;
    fs::write(version_dir.join("meta.json"), bytes).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to write index version metadata: {error}"),
        )
    })?;
    Ok(version)
}

fn attach_embeddings_to_chunks(
    chunks: &mut [Value],
    embeddings: Vec<Vec<f64>>,
) -> Result<(), ApiError> {
    if chunks.len() != embeddings.len() {
        return Err(api_error(
            StatusCode::BAD_GATEWAY,
            "Embedding provider returned a mismatched number of chunk vectors",
        ));
    }
    for (chunk, embedding) in chunks.iter_mut().zip(embeddings) {
        chunk["embedding"] = json!(embedding);
    }
    Ok(())
}

fn write_knowledge_index_files(
    version_dir: &FsPath,
    signature: &Value,
    chunks: Vec<Value>,
) -> Result<(), ApiError> {
    let chunk_index = json!({
        "provider": DEFAULT_RAG_PROVIDER,
        "signature": signature.clone(),
        "chunk_size_words": KNOWLEDGE_CHUNK_SIZE_WORDS,
        "chunk_overlap_words": KNOWLEDGE_CHUNK_OVERLAP_WORDS,
        "chunks": chunks
    });
    write_pretty_json(
        &version_dir.join("chunks.json"),
        &chunk_index,
        "chunk index",
    )?;
    write_pretty_json(
        &version_dir.join("docstore.json"),
        &json!({ "docstore/data": chunk_index["chunks"].clone() }),
        "index version docstore",
    )?;
    write_pretty_json(
        &version_dir.join("index_store.json"),
        &json!({ "index_store/data": { "root": "socartes-rust-lexical-index" } }),
        "index version index store",
    )?;
    let mut embedding_dict = Map::new();
    let mut metadata_dict = Map::new();
    let mut text_id_to_ref_doc_id = Map::new();
    for chunk in chunk_index["chunks"].as_array().into_iter().flatten() {
        let chunk_id = chunk["chunk_id"]
            .as_str()
            .or_else(|| chunk["source_id"].as_str())
            .unwrap_or_default();
        if chunk_id.is_empty() {
            continue;
        }
        if chunk["embedding"].is_array() {
            embedding_dict.insert(chunk_id.to_string(), chunk["embedding"].clone());
            metadata_dict.insert(
                chunk_id.to_string(),
                json!({
                    "source_id": chunk["source_id"],
                    "title": chunk["title"],
                    "source": chunk["source"],
                    "page": chunk["page"],
                    "provider": chunk["provider"]
                }),
            );
            text_id_to_ref_doc_id.insert(chunk_id.to_string(), chunk["source_id"].clone());
        }
    }
    write_pretty_json(
        &version_dir.join("default__vector_store.json"),
        &json!({
            "embedding_dict": embedding_dict,
            "metadata_dict": metadata_dict,
            "text_id_to_ref_doc_id": text_id_to_ref_doc_id
        }),
        "index version vector store",
    )?;
    write_pretty_json(
        &version_dir.join("graph_store.json"),
        &json!({ "graph_dict": {} }),
        "index version graph store",
    )?;
    write_pretty_json(
        &version_dir.join("image__vector_store.json"),
        &json!({
            "embedding_dict": {},
            "metadata_dict": {},
            "text_id_to_ref_doc_id": {}
        }),
        "index version image vector store",
    )
}

fn write_pretty_json(path: &FsPath, value: &Value, label: &str) -> Result<(), ApiError> {
    let bytes = serde_json::to_vec_pretty(value).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to serialize {label}: {error}"),
        )
    })?;
    fs::write(path, bytes).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to write {label}: {error}"),
        )
    })
}

fn build_knowledge_index_chunks(state: &AppState, name: &str) -> Result<Vec<Value>, ApiError> {
    let mut chunks = Vec::new();
    let files_dir = knowledge_files_dir(state, name);
    let entries = fs::read_dir(&files_dir).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to read knowledge files for indexing: {error}"),
        )
    })?;
    let mut files = entries
        .filter_map(Result::ok)
        .filter(|entry| entry.path().is_file())
        .filter_map(|entry| {
            let filename = entry.file_name().to_str().map(ToString::to_string)?;
            is_supported_knowledge_file(&filename).then_some((filename, entry.path()))
        })
        .collect::<Vec<_>>();
    files.sort_by(|left, right| left.0.cmp(&right.0));

    for (filename, path) in files {
        let bytes = fs::read(&path).map_err(|error| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                &format!("Failed to read knowledge file for indexing: {error}"),
            )
        })?;
        let text = match extract_knowledge_file_text(&filename, &bytes) {
            Ok(text) => text,
            Err(_) if is_parser_knowledge_file(&filename) => continue,
            Err(error) => {
                return Err(api_error(
                    StatusCode::BAD_REQUEST,
                    &format!("Failed to extract text from {filename}: {error}"),
                ));
            }
        };
        for (index, content) in chunk_text_by_words(&text).into_iter().enumerate() {
            let chunk_id = format!("{filename}#chunk-{:04}", index + 1);
            chunks.push(json!({
                "source_id": format!("{name}/{chunk_id}"),
                "title": filename,
                "content": content,
                "source": filename,
                "page": Value::Null,
                "chunk_id": chunk_id,
                "provider": DEFAULT_RAG_PROVIDER
            }));
        }
    }

    if chunks.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "No extractable knowledge content found",
        ));
    }

    Ok(chunks)
}

fn chunk_text_by_words(text: &str) -> Vec<String> {
    let normalized = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if normalized.is_empty() {
        return Vec::new();
    }
    let words = normalized.split_whitespace().collect::<Vec<_>>();
    if words.len() <= KNOWLEDGE_CHUNK_SIZE_WORDS {
        return vec![normalized];
    }

    let step = KNOWLEDGE_CHUNK_SIZE_WORDS
        .saturating_sub(KNOWLEDGE_CHUNK_OVERLAP_WORDS)
        .max(1);
    let mut chunks = Vec::new();
    let mut start = 0;
    while start < words.len() {
        let end = (start + KNOWLEDGE_CHUNK_SIZE_WORDS).min(words.len());
        chunks.push(words[start..end].join(" "));
        if end == words.len() {
            break;
        }
        start += step;
    }
    chunks
}

async fn rewrite_active_knowledge_index(state: &AppState, name: &str) -> Result<bool, ApiError> {
    let metadata = read_knowledge_metadata(state, name).unwrap_or_else(|| json!({}));
    let versions = knowledge_index_versions(&knowledge_base_dir(state, name), &metadata);
    let Some(active) = find_active_index_version(state, &versions) else {
        return Ok(false);
    };
    let version_dir = active["version_path"]
        .as_str()
        .or_else(|| active["storage_path"].as_str())
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            knowledge_base_dir(state, name).join(active["version"].as_str().unwrap_or("version-1"))
        });
    let mut chunks = build_knowledge_index_chunks(state, name)?;
    let texts = chunks
        .iter()
        .map(|chunk| chunk["content"].as_str().unwrap_or_default().to_string())
        .collect::<Vec<_>>();
    let embeddings = embed_knowledge_texts(state, &texts).await?;
    attach_embeddings_to_chunks(&mut chunks, embeddings)?;
    write_knowledge_index_files(&version_dir, &active["signature"], chunks)?;
    Ok(true)
}

fn sha256_hex(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    format!("{digest:x}")
}

#[derive(Debug, Clone)]
struct SavedKnowledgeFile {
    filename: String,
    hash: String,
}

fn saved_files_with_extractable_knowledge_content(
    state: &AppState,
    name: &str,
    saved_files: &[SavedKnowledgeFile],
) -> Vec<SavedKnowledgeFile> {
    let files_dir = knowledge_files_dir(state, name);
    saved_files
        .iter()
        .filter_map(|file| {
            let bytes = fs::read(files_dir.join(&file.filename)).ok()?;
            let text = extract_knowledge_file_text(&file.filename, &bytes).ok()?;
            (!chunk_text_by_words(&text).is_empty()).then(|| file.clone())
        })
        .collect()
}

fn existing_file_hashes(metadata: &Value) -> Map<String, Value> {
    metadata["file_hashes"]
        .as_object()
        .cloned()
        .unwrap_or_default()
}

fn existing_knowledge_content_hashes(
    state: &AppState,
    name: &str,
) -> Result<HashSet<String>, ApiError> {
    let files_dir = knowledge_files_dir(state, name);
    let entries = fs::read_dir(&files_dir).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to read existing knowledge files: {error}"),
        )
    })?;
    let mut hashes = HashSet::new();
    for entry in entries.filter_map(Result::ok) {
        let path = entry.path();
        if !path.is_file() {
            continue;
        }
        let Some(filename) = entry.file_name().to_str().map(ToString::to_string) else {
            continue;
        };
        if !is_supported_knowledge_file(&filename) {
            continue;
        }
        let bytes = fs::read(&path).map_err(|error| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                &format!("Failed to read existing knowledge file for duplicate check: {error}"),
            )
        })?;
        hashes.insert(sha256_hex(&bytes));
    }
    Ok(hashes)
}

fn write_knowledge_metadata_value(
    state: &AppState,
    name: &str,
    metadata: &Value,
) -> Result<(), ApiError> {
    let dir = knowledge_base_dir(state, name);
    fs::create_dir_all(&dir).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to create knowledge base directory: {error}"),
        )
    })?;
    let bytes = serde_json::to_vec_pretty(metadata).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to serialize knowledge metadata: {error}"),
        )
    })?;
    fs::write(knowledge_metadata_path(state, name), bytes).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to write knowledge metadata: {error}"),
        )
    })
}

fn write_upload_metadata(
    state: &AppState,
    name: &str,
    processed_files: &[SavedKnowledgeFile],
) -> Result<(), ApiError> {
    if processed_files.is_empty() {
        return Ok(());
    }

    let now = now_label();
    let mut metadata = read_knowledge_metadata(state, name)
        .filter(Value::is_object)
        .unwrap_or_else(|| json!({ "created_at": now.clone() }));
    if !metadata["created_at"].is_string() {
        metadata["created_at"] = json!(now.clone());
    }
    let embedding = active_knowledge_embedding_config(state);
    metadata["rag_provider"] = json!(DEFAULT_RAG_PROVIDER);
    metadata["needs_reindex"] = json!(false);
    metadata["embedding_mismatch"] = json!(false);
    metadata["embedding_model"] = json!(embedding.model);
    metadata["embedding_dim"] = json!(embedding.dimension);
    metadata["embedding_signature"] = json!(embedding.signature);
    metadata["last_updated"] = json!(now.clone());
    metadata["last_indexed_at"] = json!(now.clone());
    metadata["last_indexed_count"] = json!(processed_files.len());
    metadata["last_indexed_action"] = json!("upload");

    let mut file_hashes = existing_file_hashes(&metadata);
    for file in processed_files {
        file_hashes.insert(file.filename.clone(), json!(file.hash));
    }
    metadata["file_hashes"] = Value::Object(file_hashes);

    let mut history = metadata["update_history"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    history.push(json!({
        "timestamp": now,
        "action": "incremental_add",
        "count": processed_files.len(),
        "provider": DEFAULT_RAG_PROVIDER
    }));
    metadata["update_history"] = Value::Array(history);

    write_knowledge_metadata_value(state, name, &metadata)
}

fn read_knowledge_metadata(state: &AppState, name: &str) -> Option<Value> {
    read_knowledge_metadata_at_dir(&knowledge_base_dir(state, name))
}

fn read_knowledge_metadata_at_dir(kb_dir: &FsPath) -> Option<Value> {
    let text = fs::read_to_string(kb_dir.join("metadata.json")).ok()?;
    serde_json::from_str(&text).ok()
}

fn write_knowledge_metadata(
    state: &AppState,
    name: &str,
    _provider: &str,
    extra: Option<Value>,
) -> Result<(), ApiError> {
    let dir = knowledge_base_dir(state, name);
    fs::create_dir_all(dir.join("files")).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to create knowledge base: {error}"),
        )
    })?;

    let existing = read_knowledge_metadata(state, name);
    let created_at = existing
        .as_ref()
        .and_then(|value| value["created_at"].as_str())
        .map(ToString::to_string)
        .unwrap_or_else(now_label);

    let embedding = active_knowledge_embedding_config(state);
    let mut metadata = json!({
        "created_at": created_at,
        "last_updated": now_label(),
        "last_indexed_at": now_label(),
        "last_indexed_action": "upsert",
        "last_indexed_count": knowledge_files(state, name).unwrap_or_default().len(),
        "rag_provider": DEFAULT_RAG_PROVIDER,
        "embedding_model": embedding.model,
        "embedding_dim": embedding.dimension,
        "embedding_signature": embedding.signature,
        "needs_reindex": false,
        "embedding_mismatch": false
    });

    if let Some(Value::Object(extra)) = extra
        && let Some(object) = metadata.as_object_mut()
    {
        for (key, value) in extra {
            object.insert(key, value);
        }
    }

    let bytes = serde_json::to_vec_pretty(&metadata).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to serialize knowledge metadata: {error}"),
        )
    })?;
    fs::write(knowledge_metadata_path(state, name), bytes).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to write knowledge metadata: {error}"),
        )
    })
}

fn builtin_knowledge_file_entries() -> Vec<(&'static str, &'static str)> {
    vec![
        (
            "agent-loop.md",
            "Socartes uses Planner, Retriever, Executor, Tool Adapter, Critic, and Reflection roles to make learner-facing answers auditable.",
        ),
        (
            "rag-notes.md",
            "RAG evidence grounds generated answers in retrieved course documents before the critic approves the response.",
        ),
    ]
}

fn builtin_knowledge_file(name: &str) -> Option<String> {
    builtin_knowledge_file_entries()
        .into_iter()
        .find(|(filename, _)| *filename == name)
        .map(|(_, content)| content.to_string())
}

fn builtin_knowledge_files() -> Vec<Value> {
    builtin_knowledge_file_entries()
        .into_iter()
        .map(|(name, content)| {
            json!({
                "name": name,
                "size": content.len(),
                "modified": 0,
                "mime_type": "text/markdown"
            })
        })
        .collect()
}

fn knowledge_files(state: &AppState, name: &str) -> Result<Vec<Value>, ApiError> {
    if name == BUILTIN_KNOWLEDGE_BASE {
        return Ok(builtin_knowledge_files());
    }
    if !knowledge_base_exists(state, name) {
        return Err(api_error(StatusCode::NOT_FOUND, "Knowledge base not found"));
    }

    knowledge_files_at_dir(&knowledge_files_dir(state, name))
}

fn knowledge_files_at_dir(dir: &FsPath) -> Result<Vec<Value>, ApiError> {
    let mut files = Vec::new();
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.filter_map(Result::ok) {
            let path = entry.path();
            if !path.is_file() {
                continue;
            }
            let metadata = entry.metadata().ok();
            let modified = metadata
                .as_ref()
                .and_then(|meta| meta.modified().ok())
                .and_then(|time| time.duration_since(UNIX_EPOCH).ok())
                .map(|duration| duration.as_secs_f64())
                .unwrap_or_default();
            let size = metadata.as_ref().map(|meta| meta.len()).unwrap_or_default();
            if let Some(name) = entry.file_name().to_str() {
                files.push(json!({
                    "name": name,
                    "size": size,
                    "modified": modified,
                    "mime_type": mime_type_for(name)
                }));
            }
        }
    }
    files.sort_by(|left, right| left["name"].as_str().cmp(&right["name"].as_str()));
    Ok(files)
}

fn mime_type_for(name: &str) -> &'static str {
    match FsPath::new(name)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase()
        .as_str()
    {
        "md" | "markdown" => "text/markdown",
        "json" => "application/json",
        "csv" => "text/csv",
        "pdf" => "application/pdf",
        "docx" => "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "xlsx" => "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "pptx" => "application/vnd.openxmlformats-officedocument.presentationml.presentation",
        "htm" | "html" => "text/html",
        "svg" => "image/svg+xml",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "webp" => "image/webp",
        "mp4" => "video/mp4",
        "mp3" => "audio/mpeg",
        "wav" => "audio/wav",
        "yaml" | "yml" => "application/x-yaml",
        "tsv" => "text/tab-separated-values",
        _ => "text/plain",
    }
}

fn knowledge_file_extension(filename: &str) -> String {
    FsPath::new(filename)
        .extension()
        .and_then(|value| value.to_str())
        .map(|value| format!(".{}", value.to_ascii_lowercase()))
        .unwrap_or_default()
}

fn is_supported_knowledge_file(filename: &str) -> bool {
    let extension = knowledge_file_extension(filename);
    SUPPORTED_KNOWLEDGE_EXTENSIONS.contains(&extension.as_str())
}

fn is_parser_knowledge_file(filename: &str) -> bool {
    let extension = knowledge_file_extension(filename);
    PARSER_KNOWLEDGE_EXTENSIONS.contains(&extension.as_str())
}

fn extract_knowledge_file_text(filename: &str, bytes: &[u8]) -> Result<String, String> {
    if bytes.is_empty() {
        return Err("empty document".to_string());
    }
    if bytes.len() > MAX_KNOWLEDGE_FILE_SIZE_BYTES {
        return Err(format!(
            "document exceeds {} byte limit",
            MAX_KNOWLEDGE_FILE_SIZE_BYTES
        ));
    }

    match knowledge_file_extension(filename).as_str() {
        ".pdf" => extract_pdf_text(filename, bytes),
        ".docx" => extract_docx_text(filename, bytes),
        ".xlsx" => extract_xlsx_text(filename, bytes),
        ".pptx" => extract_pptx_text(filename, bytes),
        _ => Ok(decode_text_like(bytes)),
    }
}

fn decode_text_like(bytes: &[u8]) -> String {
    if let Ok(text) = std::str::from_utf8(bytes) {
        return text.trim_start_matches('\u{feff}').to_string();
    }

    for encoding in [encoding_rs::GBK, encoding_rs::WINDOWS_1252] {
        let (decoded, _, had_errors) = encoding.decode(bytes);
        if !had_errors {
            return decoded.trim_start_matches('\u{feff}').to_string();
        }
    }

    String::from_utf8_lossy(bytes)
        .trim_start_matches('\u{feff}')
        .to_string()
}

fn extract_pdf_text(filename: &str, bytes: &[u8]) -> Result<String, String> {
    if bytes.len() > MAX_KNOWLEDGE_PDF_SIZE_BYTES {
        return Err(format!(
            "PDF exceeds {} byte limit",
            MAX_KNOWLEDGE_PDF_SIZE_BYTES
        ));
    }
    if !bytes.starts_with(b"%PDF-") {
        return Err("invalid PDF header".to_string());
    }

    let pages = pdf_extract::extract_text_from_mem_by_pages(bytes)
        .map_err(|error| format!("PDF text extraction failed: {error}"))?;
    let text = pages
        .into_iter()
        .enumerate()
        .filter_map(|(index, page)| {
            let page = page.trim();
            (!page.is_empty()).then(|| format!("--- Page {} ---\n{page}", index + 1))
        })
        .collect::<Vec<_>>()
        .join("\n\n");
    finalize_extracted_text(filename, text)
}

fn open_ooxml_archive<'a>(
    filename: &str,
    bytes: &'a [u8],
) -> Result<zip::ZipArchive<Cursor<&'a [u8]>>, String> {
    if !bytes.starts_with(b"PK\x03\x04") {
        return Err("invalid Office Open XML header".to_string());
    }
    zip::ZipArchive::new(Cursor::new(bytes))
        .map_err(|error| format!("Failed to open {filename} as Office Open XML: {error}"))
}

fn zip_entry_names<R: Read + std::io::Seek>(archive: &mut zip::ZipArchive<R>) -> Vec<String> {
    let mut names = Vec::new();
    for index in 0..archive.len() {
        if let Ok(file) = archive.by_index(index) {
            names.push(file.name().to_string());
        }
    }
    names
}

fn read_zip_entry_to_string<R: Read + std::io::Seek>(
    archive: &mut zip::ZipArchive<R>,
    name: &str,
) -> Option<String> {
    let mut file = archive.by_name(name).ok()?;
    let mut text = String::new();
    file.read_to_string(&mut text).ok()?;
    Some(text)
}

fn extract_docx_text(filename: &str, bytes: &[u8]) -> Result<String, String> {
    let mut archive = open_ooxml_archive(filename, bytes)?;
    let mut names = zip_entry_names(&mut archive)
        .into_iter()
        .filter(|name| is_docx_text_part(name))
        .collect::<Vec<_>>();
    names.sort_by(|left, right| {
        docx_part_rank(left)
            .cmp(&docx_part_rank(right))
            .then_with(|| left.cmp(right))
    });

    let text = names
        .into_iter()
        .filter_map(|name| read_zip_entry_to_string(&mut archive, &name))
        .map(|xml| xml_text_nodes(&xml).join(" "))
        .filter(|part| !part.trim().is_empty())
        .collect::<Vec<_>>()
        .join("\n\n");
    finalize_extracted_text(filename, text)
}

fn is_docx_text_part(name: &str) -> bool {
    name == "word/document.xml"
        || (name.starts_with("word/header") && name.ends_with(".xml"))
        || (name.starts_with("word/footer") && name.ends_with(".xml"))
        || name == "word/footnotes.xml"
        || name == "word/endnotes.xml"
        || name == "word/comments.xml"
}

fn docx_part_rank(name: &str) -> usize {
    if name == "word/document.xml" { 0 } else { 1 }
}

fn extract_xlsx_text(filename: &str, bytes: &[u8]) -> Result<String, String> {
    let mut archive = open_ooxml_archive(filename, bytes)?;
    let shared_strings = read_zip_entry_to_string(&mut archive, "xl/sharedStrings.xml")
        .map(|xml| xml_text_nodes(&xml))
        .unwrap_or_default();
    let sheet_names = read_zip_entry_to_string(&mut archive, "xl/workbook.xml")
        .map(|xml| parse_xlsx_sheet_names(&xml))
        .unwrap_or_default();
    let mut worksheet_names = zip_entry_names(&mut archive)
        .into_iter()
        .filter(|name| {
            name.starts_with("xl/worksheets/sheet")
                && name.ends_with(".xml")
                && !name.contains("/_rels/")
        })
        .collect::<Vec<_>>();
    worksheet_names.sort_by(|left, right| {
        worksheet_number(left)
            .cmp(&worksheet_number(right))
            .then_with(|| left.cmp(right))
    });

    let mut sections = Vec::new();
    for (index, name) in worksheet_names.into_iter().enumerate() {
        let Some(xml) = read_zip_entry_to_string(&mut archive, &name) else {
            continue;
        };
        let rows = parse_xlsx_rows(&xml, &shared_strings);
        if rows.is_empty() {
            continue;
        }
        let sheet_name = sheet_names
            .get(index)
            .cloned()
            .unwrap_or_else(|| format!("Sheet {}", index + 1));
        let body = rows
            .into_iter()
            .map(|row| row.join("\t"))
            .collect::<Vec<_>>()
            .join("\n");
        sections.push(format!("--- Sheet: {sheet_name} ---\n{body}"));
    }

    finalize_extracted_text(filename, sections.join("\n\n"))
}

fn worksheet_number(name: &str) -> usize {
    name.rsplit_once("sheet")
        .and_then(|(_, tail)| tail.strip_suffix(".xml"))
        .and_then(|number| number.parse::<usize>().ok())
        .unwrap_or(usize::MAX)
}

fn parse_xlsx_sheet_names(xml: &str) -> Vec<String> {
    let mut reader = quick_xml::Reader::from_str(xml);
    reader.config_mut().trim_text(true);
    let mut names = Vec::new();
    loop {
        match reader.read_event() {
            Ok(quick_xml::events::Event::Start(event))
            | Ok(quick_xml::events::Event::Empty(event)) => {
                let name = event.name();
                if local_xml_name(name.as_ref()) == b"sheet"
                    && let Some(value) = xml_attribute_value(&event, b"name")
                {
                    names.push(value);
                }
            }
            Ok(quick_xml::events::Event::Eof) => break,
            Err(_) => break,
            _ => {}
        }
    }
    names
}

fn parse_xlsx_rows(xml: &str, shared_strings: &[String]) -> Vec<Vec<String>> {
    let mut reader = quick_xml::Reader::from_str(xml);
    reader.config_mut().trim_text(true);
    let mut rows = Vec::new();
    let mut current_row = Vec::new();
    let mut current_cell_type = String::new();
    let mut current_value = String::new();
    let mut in_row = false;
    let mut capturing_value = false;

    loop {
        match reader.read_event() {
            Ok(quick_xml::events::Event::Start(event)) => {
                let name = event.name();
                match local_xml_name(name.as_ref()) {
                    b"row" => {
                        in_row = true;
                        current_row.clear();
                    }
                    b"c" => {
                        current_cell_type = xml_attribute_value(&event, b"t").unwrap_or_default();
                    }
                    b"v" => {
                        capturing_value = true;
                        current_value.clear();
                    }
                    b"t" if current_cell_type == "inlineStr" || current_cell_type == "str" => {
                        capturing_value = true;
                        current_value.clear();
                    }
                    _ => {}
                }
            }
            Ok(quick_xml::events::Event::Text(event)) if capturing_value => {
                append_xml_text(&mut current_value, decode_xml_text(&event));
            }
            Ok(quick_xml::events::Event::CData(event)) if capturing_value => {
                append_xml_text(&mut current_value, decode_xml_cdata(&event));
            }
            Ok(quick_xml::events::Event::End(event)) => {
                let name = event.name();
                match local_xml_name(name.as_ref()) {
                    b"v" | b"t" if capturing_value => {
                        let value = if current_cell_type == "s" {
                            current_value
                                .trim()
                                .parse::<usize>()
                                .ok()
                                .and_then(|index| shared_strings.get(index).cloned())
                                .unwrap_or_default()
                        } else {
                            collapse_whitespace(&current_value)
                        };
                        if in_row && !value.is_empty() {
                            current_row.push(value);
                        }
                        capturing_value = false;
                        current_value.clear();
                    }
                    b"c" => {
                        current_cell_type.clear();
                    }
                    b"row" => {
                        if !current_row.is_empty() {
                            rows.push(current_row.clone());
                        }
                        current_row.clear();
                        in_row = false;
                    }
                    _ => {}
                }
            }
            Ok(quick_xml::events::Event::Eof) => break,
            Err(_) => break,
            _ => {}
        }
    }

    rows
}

fn extract_pptx_text(filename: &str, bytes: &[u8]) -> Result<String, String> {
    let mut archive = open_ooxml_archive(filename, bytes)?;
    let mut slide_names = zip_entry_names(&mut archive)
        .into_iter()
        .filter(|name| {
            name.starts_with("ppt/slides/slide")
                && name.ends_with(".xml")
                && !name.contains("/_rels/")
        })
        .collect::<Vec<_>>();
    slide_names.sort_by(|left, right| {
        slide_number(left)
            .cmp(&slide_number(right))
            .then_with(|| left.cmp(right))
    });

    let text = slide_names
        .into_iter()
        .filter_map(|name| {
            let xml = read_zip_entry_to_string(&mut archive, &name)?;
            let body = xml_text_nodes(&xml).join(" ");
            (!body.trim().is_empty()).then(|| {
                let number = slide_number(&name);
                let number = if number == usize::MAX { 1 } else { number };
                format!("--- Slide {number} ---\n{body}")
            })
        })
        .collect::<Vec<_>>()
        .join("\n\n");
    finalize_extracted_text(filename, text)
}

fn slide_number(name: &str) -> usize {
    name.rsplit_once("slide")
        .and_then(|(_, tail)| tail.strip_suffix(".xml"))
        .and_then(|number| number.parse::<usize>().ok())
        .unwrap_or(usize::MAX)
}

fn xml_text_nodes(xml: &str) -> Vec<String> {
    let mut reader = quick_xml::Reader::from_str(xml);
    reader.config_mut().trim_text(true);
    let mut texts = Vec::new();
    loop {
        match reader.read_event() {
            Ok(quick_xml::events::Event::Text(event)) => {
                if let Some(text) = decode_xml_text(&event) {
                    texts.push(text);
                }
            }
            Ok(quick_xml::events::Event::CData(event)) => {
                if let Some(text) = decode_xml_cdata(&event) {
                    texts.push(text);
                }
            }
            Ok(quick_xml::events::Event::Eof) => break,
            Err(_) => break,
            _ => {}
        }
    }
    texts
}

fn append_xml_text(target: &mut String, value: Option<String>) {
    let Some(value) = value else {
        return;
    };
    if value.is_empty() {
        return;
    }
    if !target.is_empty() {
        target.push(' ');
    }
    target.push_str(&value);
}

fn decode_xml_text(event: &quick_xml::events::BytesText<'_>) -> Option<String> {
    let decoded = event.xml10_content().ok()?;
    let unescaped = quick_xml::escape::unescape(&decoded)
        .map(|value| value.into_owned())
        .unwrap_or_else(|_| decoded.into_owned());
    let text = collapse_whitespace(&unescaped);
    (!text.is_empty()).then_some(text)
}

fn decode_xml_cdata(event: &quick_xml::events::BytesCData<'_>) -> Option<String> {
    let decoded = event.xml10_content().ok()?;
    let text = collapse_whitespace(&decoded);
    (!text.is_empty()).then_some(text)
}

fn xml_attribute_value(
    event: &quick_xml::events::BytesStart<'_>,
    expected_name: &[u8],
) -> Option<String> {
    event
        .attributes()
        .filter_map(Result::ok)
        .find(|attribute| local_xml_name(attribute.key.as_ref()) == expected_name)
        .map(|attribute| String::from_utf8_lossy(attribute.value.as_ref()).to_string())
}

fn local_xml_name(name: &[u8]) -> &[u8] {
    name.iter()
        .position(|byte| *byte == b':')
        .map(|index| &name[index + 1..])
        .unwrap_or(name)
}

fn collapse_whitespace(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn finalize_extracted_text(filename: &str, text: String) -> Result<String, String> {
    let text = text
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>()
        .join("\n");
    if text.is_empty() {
        Err(format!("No extractable text found in {filename}"))
    } else {
        Ok(text)
    }
}

async fn save_knowledge_base_from_multipart(
    state: &AppState,
    mut multipart: Multipart,
    target_name: Option<String>,
) -> Result<(String, String, Vec<String>), ApiError> {
    let is_upload = target_name.is_some();
    let mut name = target_name;
    let mut provider = DEFAULT_RAG_PROVIDER.to_string();
    let mut files = Vec::<(String, Vec<u8>)>::new();

    while let Some(field) = multipart.next_field().await.map_err(|error| {
        api_error(
            StatusCode::BAD_REQUEST,
            &format!("Invalid multipart form: {error}"),
        )
    })? {
        let field_name = field.name().unwrap_or_default().to_string();
        let file_name = field.file_name().and_then(safe_filename);
        let bytes = field.bytes().await.map_err(|error| {
            api_error(
                StatusCode::BAD_REQUEST,
                &format!("Failed to read multipart field: {error}"),
            )
        })?;

        match field_name.as_str() {
            "name" if name.is_none() => {
                let parsed = String::from_utf8(bytes.to_vec()).map_err(|_| {
                    api_error(StatusCode::BAD_REQUEST, "Knowledge base name must be UTF-8")
                })?;
                name = Some(parsed);
            }
            "rag_provider" => {
                provider = String::from_utf8(bytes.to_vec())
                    .unwrap_or_else(|_| DEFAULT_RAG_PROVIDER.to_string())
                    .trim()
                    .to_string();
                if provider.is_empty() {
                    provider = DEFAULT_RAG_PROVIDER.to_string();
                }
            }
            "files" => {
                let Some(file_name) = file_name else {
                    return Err(api_error(StatusCode::BAD_REQUEST, "Missing filename"));
                };
                if !is_supported_knowledge_file(&file_name) {
                    return Err(api_error(StatusCode::BAD_REQUEST, "Unsupported file type"));
                }
                files.push((file_name, bytes.to_vec()));
            }
            _ => {}
        }
    }

    let name = name
        .and_then(|value| safe_storage_component(&value))
        .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "Knowledge base name is required"))?;
    if name == BUILTIN_KNOWLEDGE_BASE {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "Cannot overwrite the built-in Socartes course",
        ));
    }
    if !is_upload && knowledge_base_exists(state, &name) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            &format!("Knowledge base '{name}' already exists"),
        ));
    }
    if files.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "At least one supported file is required",
        ));
    }

    if is_upload {
        if !knowledge_base_exists(state, &name) {
            return Err(api_error(StatusCode::NOT_FOUND, "Knowledge base not found"));
        }
        if knowledge_needs_reindex_for_upload(state, &name) {
            return Err(knowledge_needs_reindex_error(&name));
        }
        if !knowledge_has_active_index(state, &name) {
            return Err(api_error(
                StatusCode::CONFLICT,
                &format!(
                    "Knowledge base '{name}' does not have an active index; reindex before uploading new files"
                ),
            ));
        }
    }

    let files_dir = knowledge_files_dir(state, &name);
    fs::create_dir_all(&files_dir).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to create knowledge file directory: {error}"),
        )
    })?;

    let mut response_files = Vec::new();
    if is_upload {
        let metadata = read_knowledge_metadata(state, &name).unwrap_or_else(|| json!({}));
        let mut known_hashes = existing_file_hashes(&metadata)
            .values()
            .filter_map(Value::as_str)
            .map(ToString::to_string)
            .collect::<HashSet<_>>();
        known_hashes.extend(existing_knowledge_content_hashes(state, &name)?);
        let mut saved_files = Vec::new();
        for (filename, bytes) in files {
            let hash = sha256_hex(&bytes);
            if known_hashes.contains(&hash) {
                continue;
            }
            fs::write(files_dir.join(&filename), bytes).map_err(|error| {
                api_error(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    &format!("Failed to write uploaded file: {error}"),
                )
            })?;
            known_hashes.insert(hash.clone());
            saved_files.push(SavedKnowledgeFile { filename, hash });
        }
        if !saved_files.is_empty() {
            if !rewrite_active_knowledge_index(state, &name).await? {
                return Err(api_error(
                    StatusCode::CONFLICT,
                    &format!(
                        "Knowledge base '{name}' does not have an active index; reindex before uploading new files"
                    ),
                ));
            }
            write_upload_metadata(state, &name, &saved_files)?;
        }
        response_files = saved_files
            .iter()
            .map(|file| file.filename.clone())
            .collect::<Vec<_>>();
    } else {
        for (filename, bytes) in files {
            fs::write(files_dir.join(&filename), bytes).map_err(|error| {
                api_error(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    &format!("Failed to write uploaded file: {error}"),
                )
            })?;
            response_files.push(filename);
        }
        write_knowledge_metadata(state, &name, &provider, None)?;
    }

    let task_type = if is_upload { "kb_upload" } else { "kb_init" };
    let task_id = knowledge_task_id(task_type);
    if !is_upload {
        return Ok((name, task_id, response_files));
    }
    let indexed_count = knowledge_files(state, &name).unwrap_or_default().len();
    let action = if is_upload { "upload" } else { "create" };
    let progress = json!({
        "task_id": task_id,
        "stage": "completed",
        "message": format!("Knowledge base '{name}' {action} complete"),
        "percent": 100,
        "progress_percent": 100,
        "current": indexed_count,
        "total": indexed_count,
        "indexed_count": indexed_count,
        "index_action": action,
        "timestamp": now_label()
    });
    let _ = write_knowledge_progress(state, &name, &progress);
    state
        .knowledge_tasks
        .record_completed(
            &task_id,
            task_type,
            format!("Knowledge base '{name}' {action} complete"),
            progress,
        )
        .await;

    Ok((name, task_id, response_files))
}

async fn save_knowledge_upload_files_from_multipart(
    state: &AppState,
    name: &str,
    mut multipart: Multipart,
) -> Result<Vec<SavedKnowledgeFile>, ApiError> {
    let mut files = Vec::<(String, Vec<u8>)>::new();

    while let Some(field) = multipart.next_field().await.map_err(|error| {
        api_error(
            StatusCode::BAD_REQUEST,
            &format!("Invalid multipart form: {error}"),
        )
    })? {
        let field_name = field.name().unwrap_or_default().to_string();
        let file_name = field.file_name().and_then(safe_filename);
        let bytes = field.bytes().await.map_err(|error| {
            api_error(
                StatusCode::BAD_REQUEST,
                &format!("Failed to read multipart field: {error}"),
            )
        })?;

        if field_name == "files" {
            let Some(file_name) = file_name else {
                return Err(api_error(StatusCode::BAD_REQUEST, "Missing filename"));
            };
            if !is_supported_knowledge_file(&file_name) {
                return Err(api_error(StatusCode::BAD_REQUEST, "Unsupported file type"));
            }
            files.push((file_name, bytes.to_vec()));
        }
    }

    if files.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "At least one supported file is required",
        ));
    }

    let files_dir = knowledge_files_dir(state, name);
    fs::create_dir_all(&files_dir).map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to create knowledge file directory: {error}"),
        )
    })?;

    let metadata = read_knowledge_metadata(state, name).unwrap_or_else(|| json!({}));
    let mut known_hashes = existing_file_hashes(&metadata)
        .values()
        .filter_map(Value::as_str)
        .map(ToString::to_string)
        .collect::<HashSet<_>>();
    known_hashes.extend(existing_knowledge_content_hashes(state, name)?);
    let mut saved_files = Vec::new();
    for (filename, bytes) in files {
        let hash = sha256_hex(&bytes);
        if known_hashes.contains(&hash) {
            continue;
        }
        fs::write(files_dir.join(&filename), bytes).map_err(|error| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                &format!("Failed to write uploaded file: {error}"),
            )
        })?;
        known_hashes.insert(hash.clone());
        saved_files.push(SavedKnowledgeFile { filename, hash });
    }
    Ok(saved_files)
}

async fn llm_options(State(state): State<AppState>, headers: HeaderMap) -> impl IntoResponse {
    let payload = match require_auth(&state, &headers) {
        Ok(payload) => payload,
        Err(response) => return (*response).into_response(),
    };
    if payload.role != "admin" {
        return Json(allowed_llm_options_for_user(&state, &payload.user_id)).into_response();
    }
    Json(llm_options_from_catalog(&load_settings_catalog(&state))).into_response()
}

fn llm_options_from_catalog(catalog: &Value) -> Value {
    let service = &catalog["services"]["llm"];
    let active_profile_id = trimmed_json_string(&service["active_profile_id"]).unwrap_or_default();
    let active_model_id = trimmed_json_string(&service["active_model_id"]).unwrap_or_default();
    let mut options = Vec::new();

    if let Some(profiles) = service["profiles"].as_array() {
        for profile in profiles {
            let Some(profile_id) = trimmed_json_string(&profile["id"]) else {
                continue;
            };
            let provider = trimmed_json_string(&profile["binding"]).unwrap_or_default();
            let profile_name = trimmed_json_string(&profile["name"])
                .or_else(|| (!provider.is_empty()).then(|| provider.clone()))
                .unwrap_or_else(|| "LLM".to_string());

            let Some(models) = profile["models"].as_array() else {
                continue;
            };
            for model in models {
                let Some(model_id) = trimmed_json_string(&model["id"]) else {
                    continue;
                };
                let Some(model_value) = trimmed_json_string(&model["model"]) else {
                    continue;
                };
                let mut option = Map::new();
                let is_active_default =
                    profile_id == active_profile_id && model_id == active_model_id;
                option.insert("profile_id".to_string(), json!(profile_id));
                option.insert("model_id".to_string(), json!(model_id));
                option.insert("profile_name".to_string(), json!(profile_name));
                option.insert(
                    "model_name".to_string(),
                    json!(
                        trimmed_json_string(&model["name"]).unwrap_or_else(|| model_value.clone())
                    ),
                );
                option.insert("model".to_string(), json!(model_value));
                option.insert("provider".to_string(), json!(provider));
                option.insert("is_active_default".to_string(), json!(is_active_default));
                if let Some(context_window) = positive_i64_field(&model["context_window"])
                    .or_else(|| positive_i64_field(&model["context_window_tokens"]))
                {
                    option.insert("context_window".to_string(), json!(context_window));
                }
                options.push(Value::Object(option));
            }
        }
    }

    json!({
        "active": if active_profile_id.is_empty() || active_model_id.is_empty() {
            Value::Null
        } else {
            json!({"profile_id": active_profile_id, "model_id": active_model_id})
        },
        "options": options
    })
}

fn allowed_llm_options_for_user(state: &AppState, user_id: &str) -> Value {
    let model_access = redacted_model_access_for_user(state, user_id);
    let options = model_access["llm"]
        .as_array()
        .into_iter()
        .flatten()
        .filter(|item| item["available"].as_bool().unwrap_or(false))
        .map(|item| {
            let profile_id = trimmed_json_string(&item["profile_id"]).unwrap_or_default();
            let model_id = trimmed_json_string(&item["model_id"]).unwrap_or_default();
            let name = trimmed_json_string(&item["name"])
                .or_else(|| (!profile_id.is_empty()).then(|| profile_id.clone()))
                .unwrap_or_else(|| "LLM".to_string());
            let model = trimmed_json_string(&item["model"]).unwrap_or_default();
            let label = trimmed_json_string(&item["name"])
                .or_else(|| trimmed_json_string(&item["model"]))
                .or_else(|| trimmed_json_string(&item["model_id"]))
                .unwrap_or_default();
            json!({
                "profile_id": profile_id,
                "model_id": model_id,
                "profile_name": name,
                "model_name": label,
                "label": label,
                "model": model,
                "provider": "",
                "source": "admin",
                "is_active_default": false
            })
        })
        .collect::<Vec<_>>();
    json!({
        "active": Value::Null,
        "options": options
    })
}

fn trimmed_json_string(value: &Value) -> Option<String> {
    value
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
}

fn positive_i64_field(value: &Value) -> Option<i64> {
    parse_i64_field(value).filter(|value| *value > 0)
}

async fn get_settings(State(state): State<AppState>, headers: HeaderMap) -> impl IntoResponse {
    let payload = match require_auth(&state, &headers) {
        Ok(payload) => payload,
        Err(response) => return (*response).into_response(),
    };
    if payload.role != "admin" {
        return Json(json!({
            "ui": load_ui_settings(&state),
            "model_access": redacted_model_access_for_user(&state, &payload.user_id)
        }))
        .into_response();
    }
    Json(json!({
        "ui": load_ui_settings(&state),
        "catalog": redact_settings_catalog(&load_settings_catalog(&state)),
        "providers": settings_provider_choices()
    }))
    .into_response()
}

async fn get_settings_catalog(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> impl IntoResponse {
    if let Err(response) = require_settings_admin(&state, &headers) {
        return (*response).into_response();
    }
    Json(json!({ "catalog": redact_settings_catalog(&load_settings_catalog(&state)) }))
        .into_response()
}

async fn update_settings_catalog(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(payload): Json<Value>,
) -> impl IntoResponse {
    if let Err(response) = require_settings_admin(&state, &headers) {
        return (*response).into_response();
    }
    let incoming_catalog = payload
        .get("catalog")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or_else(default_settings_catalog);
    let catalog =
        restore_masked_settings_catalog_secrets(&incoming_catalog, &load_settings_catalog(&state));
    match write_settings_json(&state, "catalog.json", &catalog) {
        Ok(()) => Json(json!({ "catalog": redact_settings_catalog(&catalog) })).into_response(),
        Err(error) => error.into_response(),
    }
}

async fn apply_settings_catalog(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(payload): Json<Value>,
) -> impl IntoResponse {
    if let Err(response) = require_settings_admin(&state, &headers) {
        return (*response).into_response();
    }
    let incoming_catalog = payload
        .get("catalog")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or_else(|| load_settings_catalog(&state));
    let catalog =
        restore_masked_settings_catalog_secrets(&incoming_catalog, &load_settings_catalog(&state));
    if let Err(error) = write_settings_json(&state, "catalog.json", &catalog) {
        return error.into_response();
    }
    let env = render_settings_env(&catalog);
    match write_settings_json(&state, "applied-env.json", &env) {
        Ok(()) => Json(json!({
            "message": "Catalog applied to the active .env configuration.",
            "catalog": redact_settings_catalog(&catalog),
            "env": redact_settings_env(&env)
        }))
        .into_response(),
        Err(error) => error.into_response(),
    }
}

