fn visualize_trace(effective_content: &str, response: &str, result: &Value) -> StudyTrace {
    let mut trace =
        SocartesOrchestrator::new().run_with_retrieved_context(effective_content, "", Vec::new());
    trace.final_answer = response.to_string();
    trace.draft.content = response.to_string();
    trace.draft.open_gaps = Vec::new();
    trace.review.status = "approved".to_string();
    trace.review.approved = true;
    trace.reflection_events.push(ReflectionEvent {
        event_type: "self_correction".to_string(),
        agent: "visual_reviewer".to_string(),
        message: format!(
            "Reviewed {} visualization output for renderability.",
            result["render_type"].as_str().unwrap_or("visualize")
        ),
    });
    trace
}

fn normalize_deep_research_config(config: &Value, knowledge_bases: &Value) -> Value {
    let mode = match config["mode"].as_str().unwrap_or("report") {
        "notes" | "report" | "comparison" | "learning_path" => config["mode"].as_str().unwrap(),
        _ => "report",
    };
    let depth = match config["depth"].as_str().unwrap_or("standard") {
        "quick" | "standard" | "deep" | "manual" => config["depth"].as_str().unwrap(),
        _ => "standard",
    };
    let has_selected_kb = knowledge_bases.as_array().is_some_and(|items| {
        items
            .iter()
            .any(|item| item.as_str().is_some_and(|value| !value.trim().is_empty()))
    });
    let mut sources = Vec::new();
    let mut seen = HashSet::new();
    if let Some(items) = config["sources"].as_array() {
        for item in items {
            let Some(source) = item.as_str() else {
                continue;
            };
            let source = match source {
                "kb" if has_selected_kb => "kb",
                "kb" => continue,
                "web" => "web",
                "papers" => "papers",
                _ => continue,
            };
            if seen.insert(source) {
                sources.push(source.to_string());
            }
        }
    }
    if sources.is_empty() {
        sources.push("web".to_string());
    }

    let mut object = Map::new();
    object.insert("mode".to_string(), json!(mode));
    object.insert("depth".to_string(), json!(depth));
    object.insert("sources".to_string(), json!(sources));
    if let Some(value) = config["manual_subtopics"].as_i64() {
        object.insert("manual_subtopics".to_string(), json!(value.clamp(1, 10)));
    }
    if let Some(value) = config["manual_max_iterations"].as_i64() {
        object.insert(
            "manual_max_iterations".to_string(),
            json!(value.clamp(1, 10)),
        );
    }
    if let Some(outline) = normalized_confirmed_outline(&config["confirmed_outline"]) {
        object.insert("confirmed_outline".to_string(), outline);
    }
    Value::Object(object)
}

fn normalized_confirmed_outline(value: &Value) -> Option<Value> {
    let items = value.as_array()?;
    let outline = items
        .iter()
        .filter_map(|item| {
            let title = item["title"].as_str()?.trim();
            if title.is_empty() {
                return None;
            }
            Some(json!({
                "title": truncate_for_prompt(title, 160),
                "overview": truncate_for_prompt(item["overview"].as_str().unwrap_or_default().trim(), 320)
            }))
        })
        .collect::<Vec<_>>();
    (!outline.is_empty()).then(|| Value::Array(outline))
}

fn build_deep_research_outline_preview(effective_content: &str, config: &Value) -> Value {
    let topic = deep_research_topic(effective_content);
    let sub_topics = deep_research_sub_topics(&topic, config);
    let response = deep_research_outline_markdown(&topic, &sub_topics, config);
    json!({
        "response": response,
        "content": response,
        "outline_preview": true,
        "sub_topics": sub_topics,
        "topic": topic,
        "research_config": config
    })
}

fn build_deep_research_confirmed_report(effective_content: &str, config: &Value) -> Value {
    let topic = deep_research_topic(effective_content);
    let sub_topics = deep_research_sub_topics(&topic, config);
    let response = deep_research_report_markdown(&topic, &sub_topics, config);
    json!({
        "response": response,
        "content": response,
        "outline_preview": false,
        "sub_topics": sub_topics,
        "topic": topic,
        "research_config": config,
        "metadata": {
            "confirmed_outline_used": true,
            "sub_topics": sub_topics,
            "sources": config["sources"].clone(),
            "mode": config["mode"].clone(),
            "depth": config["depth"].clone()
        }
    })
}

fn deep_research_topic(effective_content: &str) -> String {
    let topic = effective_content
        .lines()
        .map(str::trim)
        .filter(|line| {
            !line.is_empty() && *line != "[Attached Documents]" && *line != "[User Question]"
        })
        .take(2)
        .collect::<Vec<_>>()
        .join(" ");
    if topic.is_empty() {
        "the requested research topic".to_string()
    } else {
        truncate_for_prompt(&topic, 220)
    }
}

fn deep_research_sub_topics(topic: &str, config: &Value) -> Vec<Value> {
    if let Some(outline) = config["confirmed_outline"].as_array()
        && !outline.is_empty()
    {
        return outline.to_vec();
    }
    let count = config["manual_subtopics"]
        .as_u64()
        .map(|value| value.clamp(1, 10) as usize)
        .unwrap_or_else(|| match config["depth"].as_str().unwrap_or("standard") {
            "quick" => 2,
            "deep" => 4,
            "manual" => 3,
            _ => 3,
        });
    let templates = match config["mode"].as_str().unwrap_or("report") {
        "comparison" => vec![
            (
                "Conceptual frame",
                "Define each side and establish the comparison criteria.",
            ),
            (
                "Retrieval workflow",
                "Compare how knowledge is selected, refined, and reused.",
            ),
            (
                "Agent control loop",
                "Identify where planning, tools, and reflection change the outcome.",
            ),
            (
                "Evaluation risks",
                "Assess citation quality, latency, cost, and failure modes.",
            ),
        ],
        "learning_path" => vec![
            (
                "Prerequisites",
                "Identify the learner's starting assumptions and vocabulary.",
            ),
            (
                "Core sequence",
                "Arrange the topic into teachable milestones.",
            ),
            (
                "Practice loop",
                "Define checks, exercises, and revision triggers.",
            ),
            (
                "Mastery evidence",
                "Specify artifacts that prove understanding.",
            ),
        ],
        "notes" => vec![
            ("Key ideas", "Extract the durable concepts and terms."),
            ("Evidence map", "Attach supporting references and examples."),
            ("Review prompts", "Turn findings into study questions."),
            ("Open gaps", "List unclear points for follow-up."),
        ],
        _ => vec![
            ("Background", "Establish context, terminology, and scope."),
            ("Evidence", "Collect source-backed claims and examples."),
            ("Synthesis", "Connect findings into a report structure."),
            (
                "Implications",
                "Describe limitations, next steps, and risks.",
            ),
        ],
    };
    templates
        .into_iter()
        .take(count)
        .map(|(title, overview)| {
            json!({
                "title": format!("{topic}: {title}"),
                "overview": overview
            })
        })
        .collect()
}

fn deep_research_outline_markdown(topic: &str, sub_topics: &[Value], config: &Value) -> String {
    let sources = config["sources"]
        .as_array()
        .map(|items| {
            items
                .iter()
                .filter_map(Value::as_str)
                .collect::<Vec<_>>()
                .join(", ")
        })
        .unwrap_or_default();
    let mut lines = vec![
        format!("# Research Outline Preview: {topic}"),
        String::new(),
        format!(
            "Mode: {} | Depth: {} | Sources: {}",
            config["mode"].as_str().unwrap_or("report"),
            config["depth"].as_str().unwrap_or("standard"),
            if sources.is_empty() { "web" } else { &sources }
        ),
        String::new(),
    ];
    for (index, item) in sub_topics.iter().enumerate() {
        lines.push(format!(
            "## {}. {}",
            index + 1,
            item["title"].as_str().unwrap_or("Research section")
        ));
        let overview = item["overview"].as_str().unwrap_or_default();
        if !overview.is_empty() {
            lines.push(overview.to_string());
        }
        lines.push(String::new());
    }
    lines.join("\n").trim_end().to_string()
}

fn deep_research_report_markdown(topic: &str, sub_topics: &[Value], config: &Value) -> String {
    let sources = config["sources"]
        .as_array()
        .map(|items| {
            items
                .iter()
                .filter_map(Value::as_str)
                .collect::<Vec<_>>()
                .join(", ")
        })
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "web".to_string());
    let mut lines = vec![
        format!("# Research Report: {topic}"),
        String::new(),
        format!(
            "Mode: {} | Depth: {} | Sources: {}",
            config["mode"].as_str().unwrap_or("report"),
            config["depth"].as_str().unwrap_or("standard"),
            sources
        ),
        String::new(),
        "This report was generated from a user-confirmed outline and keeps the confirmed section order.".to_string(),
        String::new(),
    ];
    for (index, item) in sub_topics.iter().enumerate() {
        let title = item["title"].as_str().unwrap_or("Research section");
        let overview = item["overview"].as_str().unwrap_or_default();
        lines.push(format!("## {}. {title}", index + 1));
        if !overview.is_empty() {
            lines.push(overview.to_string());
        }
        lines.push(format!(
            "Finding: {title} frames the requested topic, `{topic}`, using the selected research sources."
        ));
        lines.push(format!(
            "Evidence plan: validate claims against {sources} sources before using this section in downstream answers."
        ));
        lines.push(String::new());
    }
    lines.push("## Synthesis".to_string());
    lines.push(format!(
        "The confirmed outline yields {} section(s) that can be researched, cited, and revised independently.",
        sub_topics.len()
    ));
    lines.join("\n").trim_end().to_string()
}

fn deep_research_trace(effective_content: &str, response: &str, result: &Value) -> StudyTrace {
    let mut trace =
        SocartesOrchestrator::new().run_with_retrieved_context(effective_content, "", Vec::new());
    trace.final_answer = response.to_string();
    trace.draft.content = response.to_string();
    trace.draft.open_gaps = Vec::new();
    trace.review.status = "approved".to_string();
    trace.review.approved = true;
    let result_kind = if result["outline_preview"].as_bool().unwrap_or(false) {
        "outline preview"
    } else {
        "confirmed report"
    };
    trace.reflection_events.push(ReflectionEvent {
        event_type: "self_correction".to_string(),
        agent: "research_planner".to_string(),
        message: format!(
            "Generated {} deep_research {result_kind} sections.",
            result["sub_topics"]
                .as_array()
                .map(Vec::len)
                .unwrap_or_default()
        ),
    });
    trace
}

fn build_deep_question_result(effective_content: &str, config: &Value) -> Value {
    let mode = normalize_deep_question_mode(
        config["mode"]
            .as_str()
            .or_else(|| config["question_mode"].as_str())
            .unwrap_or("custom"),
    );
    let requested = deep_question_count(config);
    let question_type = normalize_deep_question_type(
        config["question_type"]
            .as_str()
            .or_else(|| config["type"].as_str())
            .unwrap_or("choice"),
    );
    let difficulty = config["difficulty"].as_str().unwrap_or("medium");
    let topic = deep_question_topic(effective_content, config, &mode);
    let mut results = Vec::new();
    let mut response_sections = Vec::new();
    for index in 0..requested {
        let number = index + 1;
        let stem = format!(
            "Question {number}: Which statement best reflects {topic} for a {difficulty} learner?"
        );
        let options = json!({
            "A": format!("A focused explanation of {topic}"),
            "B": "An unrelated distractor that ignores the supplied material",
            "C": "A partial answer without evidence",
            "D": "A response that changes the topic"
        });
        let explanation =
            format!("The correct answer stays grounded in the requested topic: {topic}.");
        response_sections.push(format!(
            "### Question {number}\n{stem}\n\nA. {}\nB. {}\nC. {}\nD. {}\n\n**Answer:** A\n\n**Explanation:** {explanation}",
            options["A"].as_str().unwrap_or_default(),
            options["B"].as_str().unwrap_or_default(),
            options["C"].as_str().unwrap_or_default(),
            options["D"].as_str().unwrap_or_default()
        ));
        results.push(json!({
            "status": "success",
            "qa_pair": {
                "question_id": format!("q_{number}"),
                "question": stem,
                "options": options,
                "correct_answer": "A",
                "explanation": explanation,
                "question_type": question_type,
                "difficulty": difficulty,
                "concentration": topic,
                "knowledge_context": topic,
                "metadata": {
                    "knowledge_context": topic,
                    "mode": mode
                }
            }
        }));
    }
    let response = response_sections.join("\n\n");
    json!({
        "response": response,
        "content": response,
        "mode": mode,
        "summary": {
            "success": true,
            "requested": requested,
            "completed": requested,
            "failed": 0,
            "results": results
        }
    })
}

fn build_deep_question_followup_result(user_question: &str, config: &Value) -> Option<Value> {
    let context = config["followup_question_context"].as_object()?;
    let question = context
        .get("question")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let question_id = context
        .get("question_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("q_1");
    let correct_answer = context
        .get("correct_answer")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("the expected answer");
    let user_answer = context
        .get("user_answer")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("your submitted answer");
    let explanation = context
        .get("explanation")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(question);
    let learner_question = user_question.trim();
    let response = format!(
        "Follow-up for {question_id}: {learner_question}\n\nThe referenced question was: {question}\n\nYour answer was {user_answer}. The expected answer is {correct_answer}. {explanation}"
    );

    Some(json!({
        "response": response,
        "content": response,
        "mode": "followup",
        "question_id": question_id,
        "metadata": {
            "cost_summary": {
                "total_cost_usd": 0,
                "total_tokens": 0,
                "total_calls": 0
            }
        }
    }))
}

fn build_deep_question_answer_now_result(effective_content: &str, config: &Value) -> Option<Value> {
    config["answer_now_context"].as_object()?;
    let base = build_deep_question_result(effective_content, config);
    let base_response = base["response"].as_str().unwrap_or_default();
    let response = format!(
        "> Skipped ideation and generated the requested quiz immediately.\n\n{base_response}"
    );
    let mut summary = base["summary"].clone();
    summary["mode"] = json!("answer_now");
    if let Some(results) = summary["results"].as_array_mut() {
        for item in results {
            item["metadata"] = json!({ "answer_now": true });
        }
    }

    Some(json!({
        "response": response,
        "content": response,
        "mode": "answer_now",
        "summary": summary,
        "metadata": {
            "answer_now": true,
            "cost_summary": {
                "total_cost_usd": 0,
                "total_tokens": 0,
                "total_calls": 0
            }
        }
    }))
}

fn deep_question_count(config: &Value) -> usize {
    config["num_questions"]
        .as_u64()
        .or_else(|| config["max_questions"].as_u64())
        .or_else(|| config["count"].as_u64())
        .unwrap_or(1)
        .clamp(1, 50) as usize
}

fn normalize_deep_question_mode(value: &str) -> String {
    match value.trim().to_ascii_lowercase().as_str() {
        "mimic" => "mimic".to_string(),
        "followup" | "follow_up" => "followup".to_string(),
        _ => "custom".to_string(),
    }
}

fn normalize_deep_question_type(value: &str) -> String {
    match value.trim().to_ascii_lowercase().as_str() {
        "multiple_choice" | "single_choice" | "mcq" | "choice" => "choice".to_string(),
        "short_answer" | "short" => "short_answer".to_string(),
        "true_false" | "boolean" => "true_false".to_string(),
        other if !other.is_empty() => other.to_string(),
        _ => "choice".to_string(),
    }
}

fn deep_question_topic(effective_content: &str, config: &Value, mode: &str) -> String {
    let configured = config["topic"]
        .as_str()
        .or_else(|| config["requirement"].as_str())
        .or_else(|| config["paper_path"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let source = if mode == "mimic" {
        effective_content.trim()
    } else {
        configured.unwrap_or_else(|| effective_content.trim())
    };
    let cleaned = source
        .lines()
        .map(str::trim)
        .filter(|line| {
            !line.is_empty()
                && *line != "[Attached Documents]"
                && *line != "[User Question]"
                && !line.starts_with("Filename:")
        })
        .take(3)
        .collect::<Vec<_>>()
        .join(" ");
    let topic = if cleaned.is_empty() {
        "the requested topic"
    } else {
        cleaned.as_str()
    };
    truncate_for_prompt(topic, 180)
}

fn deep_question_trace(effective_content: &str, response: &str, result: &Value) -> StudyTrace {
    let mut trace =
        SocartesOrchestrator::new().run_with_retrieved_context(effective_content, "", Vec::new());
    trace.final_answer = response.to_string();
    trace.draft.content = response.to_string();
    trace.draft.open_gaps = Vec::new();
    trace.review.status = "approved".to_string();
    trace.review.approved = true;
    trace.reflection_events.push(ReflectionEvent {
        event_type: "self_correction".to_string(),
        agent: "question_critic".to_string(),
        message: format!(
            "Generated {} normalized quiz questions for deep_question.",
            result["summary"]["completed"].as_u64().unwrap_or_default()
        ),
    });
    trace
}

fn plugin_request_params(payload: &Value) -> Value {
    payload
        .get("params")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or_else(|| json!({}))
}

async fn plugin_tool_result(
    state: &AppState,
    tool_name: &str,
    params: Value,
    auth_payload: Option<&AuthTokenPayload>,
) -> Result<Value, ApiError> {
    if !plugin_tool_names().contains(&tool_name) {
        return Err(api_error(
            StatusCode::NOT_FOUND,
            &format!("Tool '{tool_name}' not found"),
        ));
    }

    let (success, content, sources, metadata) = match tool_name {
        "brainstorm" => {
            let topic = string_param(&params, "topic").unwrap_or("the current Socartes task");
            let context = string_param(&params, "context").unwrap_or("");
            (
                true,
                format!(
                    "Brainstorm for {topic}: define the learning goal, retrieve course evidence, run the agent workflow, and check the answer. {context}"
                ),
                json!([]),
                json!({ "tool": "brainstorm", "topic": topic, "context": context }),
            )
        }
        "course_context" => {
            let knowledge_bases = params
                .get("knowledge_bases")
                .and_then(Value::as_array)
                .map(|items| {
                    items
                        .iter()
                        .filter_map(|item| item.as_str().map(str::trim))
                        .filter(|name| !name.is_empty())
                        .map(ToString::to_string)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            let content = if knowledge_bases.is_empty() {
                "No course or knowledge base is currently selected.".to_string()
            } else {
                format!(
                    "Current selected course / knowledge base: {}",
                    knowledge_bases.join(", ")
                )
            };
            (
                true,
                content,
                json!([]),
                json!({ "tool": "course_context", "knowledge_bases": knowledge_bases }),
            )
        }
        "rag" => {
            let query = string_param(&params, "query").unwrap_or_default();
            let kb_names = string_param(&params, "kb_name")
                .filter(|value| !value.is_empty())
                .map(|value| vec![value.to_string()])
                .unwrap_or_else(|| {
                    if auth_payload.is_some_and(|payload| payload.role != "admin") {
                        Vec::new()
                    } else {
                        vec![read_default_knowledge_base(state)]
                    }
                });
            if kb_names.is_empty() {
                return Err(api_error(
                    StatusCode::BAD_REQUEST,
                    "No knowledge base selected. Pass kb_name explicitly or set a default.",
                ));
            }
            let chunks = if let Some(payload) = auth_payload {
                retrieve_chat_context_for_auth(state, query, &kb_names, payload).await?
            } else {
                retrieve_chat_context(state, query, &kb_names).await
            };
            let content = if chunks.is_empty() {
                format!("No Socartes knowledge base passages matched query: {query}")
            } else {
                chunks
                    .iter()
                    .map(|chunk| format!("{}: {}", chunk.source_id, chunk.content))
                    .collect::<Vec<_>>()
                    .join("\n\n")
            };
            let sources = Value::Array(
                chunks
                    .iter()
                    .map(|chunk| {
                        json!({
                            "type": "rag",
                            "source_id": chunk.source_id,
                            "title": chunk.title,
                            "content": chunk.content,
                            "confidence": chunk.confidence,
                            "provider": chunk.provider.as_deref().unwrap_or(DEFAULT_RAG_PROVIDER),
                            "source": chunk.source,
                            "page": chunk.page,
                            "chunk_id": chunk.chunk_id,
                            "score": chunk.score
                        })
                    })
                    .collect(),
            );
            (
                true,
                content,
                sources,
                json!({ "provider": DEFAULT_RAG_PROVIDER, "query": query, "knowledge_bases": kb_names }),
            )
        }
        "web_search" => {
            let query = string_param(&params, "query").unwrap_or_default();
            let catalog = load_settings_catalog(state);
            let config = resolve_search_runtime_config(&catalog);
            let result = run_web_search(&config, query).await.map_err(|error| {
                api_error(
                    StatusCode::BAD_GATEWAY,
                    &format!("Web search provider request failed: {error}"),
                )
            })?;
            let content = if result.answer.trim().is_empty() {
                format_search_results_answer(query, &result.search_results)
            } else {
                result.answer.clone()
            };
            (
                true,
                content,
                web_search_sources(&result),
                web_search_metadata(&config, &result, query),
            )
        }
        "code_execution" => {
            let intent = string_param(&params, "intent")
                .or_else(|| string_param(&params, "query"))
                .unwrap_or("Run a Socartes calculation");
            let code = string_param(&params, "code").unwrap_or("");
            (
                true,
                if code.is_empty() {
                    format!("Code execution compatibility accepted intent: {intent}")
                } else {
                    format!("Code execution compatibility accepted code for intent '{intent}'.")
                },
                json!([]),
                json!({ "intent": intent, "code": code, "exit_code": 0, "artifacts": [] }),
            )
        }
        "reason" => {
            let query = string_param(&params, "query").unwrap_or_default();
            let context = string_param(&params, "context").unwrap_or("");
            (
                true,
                format!(
                    "Reasoned answer for '{query}' using Socartes planner/executor/critic structure. {context}"
                ),
                json!([]),
                json!({ "query": query, "context": context }),
            )
        }
        "paper_search" => {
            let query = string_param(&params, "query").unwrap_or_default();
            (
                true,
                format!("No arXiv preprints were fetched in compatibility mode for query: {query}"),
                json!([]),
                json!({ "provider": "arxiv", "query": query, "papers": [] }),
            )
        }
        "geogebra_analysis" => {
            let question = string_param(&params, "question").unwrap_or_default();
            (
                true,
                format!("GeoGebra compatibility analysis received question: {question}"),
                json!([]),
                json!({ "question": question, "final_ggb_commands": [] }),
            )
        }
        _ => unreachable!("tool name was checked"),
    };

    Ok(json!({
        "success": success,
        "content": content,
        "sources": sources,
        "metadata": metadata
    }))
}

fn string_param<'a>(params: &'a Value, key: &str) -> Option<&'a str> {
    params
        .get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn plugin_tool_names() -> Vec<&'static str> {
    vec![
        "brainstorm",
        "course_context",
        "rag",
        "web_search",
        "code_execution",
        "reason",
        "paper_search",
        "geogebra_analysis",
    ]
}

fn plugin_tool_definitions() -> Value {
    json!([
        {
            "name": "brainstorm",
            "description": "Broadly explore multiple possibilities for a topic and give a short rationale for each.",
            "parameters": [
                tool_parameter("topic", "string", "The topic, goal, or problem to brainstorm about.", true, Value::Null, Value::Null),
                tool_parameter("context", "string", "Optional supporting context, constraints, or background.", false, Value::Null, Value::Null)
            ]
        },
        {
            "name": "course_context",
            "description": "Return the current selected Socartes course or knowledge base for this chat turn. The backend injects the active course list.",
            "parameters": []
        },
        {
            "name": "rag",
            "description": "Search a knowledge base using Retrieval-Augmented Generation. Returns relevant passages and an LLM-synthesised answer.",
            "parameters": [
                tool_parameter("query", "string", "Search query.", true, Value::Null, Value::Null),
                tool_parameter("kb_name", "string", "Knowledge base to search.", false, Value::Null, Value::Null)
            ]
        },
        {
            "name": "web_search",
            "description": "Search the web and return summarised results with citations.",
            "parameters": [
                tool_parameter("query", "string", "Search query.", true, Value::Null, Value::Null)
            ]
        },
        {
            "name": "code_execution",
            "description": "Turn a natural-language computation request into Python, run it in a restricted Python worker, and return the result.",
            "parameters": [
                tool_parameter("intent", "string", "Natural-language description of the computation or verification task.", true, Value::Null, Value::Null),
                tool_parameter("code", "string", "Optional raw Python code to execute directly.", false, Value::Null, Value::Null),
                tool_parameter("timeout", "integer", "Max execution time in seconds.", false, json!(30), Value::Null)
            ]
        },
        {
            "name": "reason",
            "description": "Perform deep reasoning on a complex sub-problem using a dedicated LLM call. Use when the current context is insufficient for a confident answer.",
            "parameters": [
                tool_parameter("query", "string", "The sub-problem to reason about.", true, Value::Null, Value::Null),
                tool_parameter("context", "string", "Supporting context for reasoning.", false, Value::Null, Value::Null)
            ]
        },
        {
            "name": "paper_search",
            "description": "Search arXiv preprints by keyword and return concise metadata.",
            "parameters": [
                tool_parameter("query", "string", "Search query.", true, Value::Null, Value::Null),
                tool_parameter("max_results", "integer", "Maximum papers to return.", false, json!(3), Value::Null),
                tool_parameter("years_limit", "integer", "Only include preprints from the last N years.", false, json!(3), Value::Null),
                tool_parameter("sort_by", "string", "Sort by relevance or submission date.", false, json!("relevance"), json!(["relevance", "date"]))
            ]
        },
        {
            "name": "geogebra_analysis",
            "description": "Analyze a math problem image, detect geometric elements, and generate validated GeoGebra commands for visualization. Requires an attached image.",
            "parameters": [
                tool_parameter("question", "string", "The math problem text to analyze.", true, Value::Null, Value::Null),
                tool_parameter("image_base64", "string", "Base64-encoded image (data URI or raw). Injected from attachments when called via function-calling.", false, json!(""), Value::Null),
                tool_parameter("language", "string", "Output language: 'zh' or 'en'.", false, json!("zh"), json!(["zh", "en"]))
            ]
        }
    ])
}

fn tool_parameter(
    name: &str,
    parameter_type: &str,
    description: &str,
    required: bool,
    default_value: Value,
    enum_values: Value,
) -> Value {
    json!({
        "name": name,
        "type": parameter_type,
        "description": description,
        "required": required,
        "default": default_value,
        "enum": enum_values
    })
}

fn requested_chat_tool_names(payload: &Value) -> Vec<String> {
    let allowed = builtin_chat_tool_name_set();
    requested_chat_tool_names_with_allowed(payload, &allowed)
}

fn requested_tutorbot_chat_tool_names(payload: &Value, config: &Value) -> Vec<String> {
    let mut allowed = builtin_chat_tool_name_set();
    allowed.extend(configured_tutorbot_mcp_tool_names(config));
    let allow_all_prefixes = tutorbot_mcp_allow_all_prefixes(config);
    let mut seen = HashSet::new();
    as_string_array(&payload["tools"])
        .into_iter()
        .filter(|name| {
            allowed.contains(name)
                || allow_all_prefixes
                    .iter()
                    .any(|prefix| name.starts_with(prefix))
        })
        .filter(|name| seen.insert(name.clone()))
        .collect()
}

fn builtin_chat_tool_name_set() -> HashSet<String> {
    plugin_tool_names()
        .into_iter()
        .map(ToString::to_string)
        .collect()
}

fn requested_chat_tool_names_with_allowed(
    payload: &Value,
    allowed_tool_names: &HashSet<String>,
) -> Vec<String> {
    let mut seen = HashSet::new();
    as_string_array(&payload["tools"])
        .into_iter()
        .filter(|name| allowed_tool_names.contains(name))
        .filter(|name| seen.insert(name.clone()))
        .collect()
}

fn configured_tutorbot_mcp_tool_names(config: &Value) -> HashSet<String> {
    let mut names = HashSet::new();
    let Some(servers) = config["tools"]["mcp_servers"].as_object() else {
        return names;
    };
    for (server_name, server_config) in servers {
        let wrapped_prefix = format!("mcp_{server_name}_");
        for tool_name in tutorbot_mcp_enabled_tools(server_config) {
            if tool_name == "*" {
                continue;
            }
            if tool_name.starts_with(&wrapped_prefix) {
                names.insert(tool_name);
            } else {
                names.insert(format!("{wrapped_prefix}{tool_name}"));
            }
        }
    }
    names
}

fn tutorbot_mcp_allow_all_prefixes(config: &Value) -> Vec<String> {
    let Some(servers) = config["tools"]["mcp_servers"].as_object() else {
        return Vec::new();
    };
    servers
        .iter()
        .filter(|(_, server_config)| {
            tutorbot_mcp_enabled_tools(server_config)
                .iter()
                .any(|tool| tool == "*")
        })
        .map(|(server_name, _)| format!("mcp_{server_name}_"))
        .collect()
}

fn tutorbot_mcp_enabled_tools(server_config: &Value) -> Vec<String> {
    if server_config.get("enabled_tools").is_none() || server_config["enabled_tools"].is_null() {
        return vec!["*".to_string()];
    }
    as_string_array(&server_config["enabled_tools"])
}

#[derive(Debug, Clone)]
struct TutorbotMcpToolDefinition {
    server_name: String,
    original_name: String,
    wrapped_name: String,
    description: String,
    input_schema: Value,
    server_config: Value,
    tool_timeout: u64,
}

async fn discover_tutorbot_mcp_tools(
    config: &Value,
    enabled_tools: &[String],
) -> Vec<TutorbotMcpToolDefinition> {
    let Some(servers) = config["tools"]["mcp_servers"].as_object() else {
        return Vec::new();
    };
    let requested = enabled_tools
        .iter()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    let mut tools = Vec::new();
    for (server_name, server_config) in servers {
        let prefix = format!("mcp_{server_name}_");
        if !requested.is_empty() && !requested.iter().any(|name| name.starts_with(&prefix)) {
            continue;
        }
        let listed = match list_tutorbot_mcp_server_tools(server_name, server_config).await {
            Ok(listed) => listed,
            Err(error) => {
                eprintln!("MCP server '{server_name}': failed to list tools: {error}");
                continue;
            }
        };
        let configured = tutorbot_mcp_enabled_tools(server_config);
        let allow_all = configured.iter().any(|name| name == "*");
        let configured = configured.into_iter().collect::<HashSet<_>>();
        for tool in listed {
            let original_name = tool["name"].as_str().unwrap_or_default().trim();
            if original_name.is_empty() {
                continue;
            }
            let wrapped_name = format!("{prefix}{original_name}");
            if !allow_all
                && !configured.contains(original_name)
                && !configured.contains(&wrapped_name)
            {
                continue;
            }
            if !requested.is_empty() && !requested.contains(wrapped_name.as_str()) {
                continue;
            }
            let input_schema = tool
                .get("inputSchema")
                .or_else(|| tool.get("input_schema"))
                .filter(|value| value.is_object())
                .cloned()
                .unwrap_or_else(|| json!({"type": "object", "properties": {}}));
            tools.push(TutorbotMcpToolDefinition {
                server_name: server_name.clone(),
                original_name: original_name.to_string(),
                wrapped_name,
                description: tool["description"]
                    .as_str()
                    .filter(|value| !value.trim().is_empty())
                    .unwrap_or(original_name)
                    .to_string(),
                input_schema,
                server_config: server_config.clone(),
                tool_timeout: tutorbot_mcp_tool_timeout(server_config),
            });
        }
    }
    tools
}

async fn list_tutorbot_mcp_server_tools(
    server_name: &str,
    server_config: &Value,
) -> Result<Vec<Value>, String> {
    let transport = tutorbot_mcp_transport_type(server_config);
    match transport.as_deref() {
        Some("streamableHttp") => {
            let _ = tutorbot_mcp_json_rpc_request(
                server_config,
                "initialize",
                json!({
                    "protocolVersion": "2024-11-05",
                    "capabilities": {},
                    "clientInfo": {
                        "name": "socartes-rust",
                        "version": VERSION
                    }
                }),
            )
            .await;
            let result =
                tutorbot_mcp_json_rpc_request(server_config, "tools/list", json!({})).await?;
            Ok(result["tools"].as_array().cloned().unwrap_or_default())
        }
        Some(other) => {
            eprintln!(
                "MCP server '{server_name}': transport '{other}' is not implemented in the Rust runtime yet"
            );
            Ok(Vec::new())
        }
        None => Ok(Vec::new()),
    }
}

fn tutorbot_mcp_transport_type(server_config: &Value) -> Option<String> {
    if let Some(value) = server_config["type"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        return Some(value.to_string());
    }
    if server_config["command"]
        .as_str()
        .map(str::trim)
        .is_some_and(|value| !value.is_empty())
    {
        return Some("stdio".to_string());
    }
    let url = server_config["url"].as_str()?.trim();
    if url.is_empty() {
        None
    } else if url.trim_end_matches('/').ends_with("/sse") {
        Some("sse".to_string())
    } else {
        Some("streamableHttp".to_string())
    }
}

async fn tutorbot_mcp_json_rpc_request(
    server_config: &Value,
    method: &str,
    params: Value,
) -> Result<Value, String> {
    let url = server_config["url"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "missing MCP server url".to_string())?;
    let timeout_secs = tutorbot_mcp_tool_timeout(server_config);
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_secs))
        .redirect(reqwest::redirect::Policy::limited(10))
        .build()
        .map_err(|error| error.to_string())?;
    let mut request = client
        .post(url)
        .header(
            reqwest::header::ACCEPT,
            "application/json, text/event-stream",
        )
        .json(&json!({
            "jsonrpc": "2.0",
            "id": format!("mcp_{}", uuid::Uuid::new_v4().simple()),
            "method": method,
            "params": params
        }));
    if let Some(headers) = server_config["headers"].as_object() {
        for (key, value) in headers {
            if let Some(value) = value.as_str() {
                request = request.header(key, value);
            }
        }
    }
    let response = request.send().await.map_err(|error| {
        if error.is_timeout() {
            format!("timeout after {timeout_secs}s")
        } else {
            error.to_string()
        }
    })?;
    let status = response.status();
    let text = response.text().await.map_err(|error| error.to_string())?;
    if !status.is_success() {
        return Err(format!("HTTP {}: {}", status.as_u16(), text.trim()));
    }
    let payload = parse_mcp_response_payload(&text)?;
    if let Some(error) = payload.get("error") {
        return Err(format!("JSON-RPC error: {error}"));
    }
    Ok(payload.get("result").cloned().unwrap_or_else(|| json!({})))
}

fn parse_mcp_response_payload(text: &str) -> Result<Value, String> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Ok(json!({}));
    }
    if let Ok(value) = serde_json::from_str::<Value>(trimmed) {
        return Ok(value);
    }
    for block in trimmed.split("\n\n") {
        let data = block
            .lines()
            .filter_map(|line| line.strip_prefix("data:"))
            .map(str::trim_start)
            .collect::<Vec<_>>()
            .join("\n");
        if !data.trim().is_empty()
            && let Ok(value) = serde_json::from_str::<Value>(&data)
        {
            return Ok(value);
        }
    }
    Err(format!("Invalid MCP JSON response: {trimmed}"))
}

fn tutorbot_mcp_tool_timeout(server_config: &Value) -> u64 {
    server_config["tool_timeout"]
        .as_u64()
        .or_else(|| {
            server_config["tool_timeout"]
                .as_str()
                .and_then(|value| value.parse::<u64>().ok())
        })
        .filter(|value| *value > 0)
        .unwrap_or(30)
}

fn supports_native_chat_tools(selection: &ChatRuntimeSelection) -> bool {
    let binding = selection.binding.to_ascii_lowercase();
    !matches!(
        binding.as_str(),
        "anthropic" | "claude" | "ollama" | "lm_studio" | "vllm" | "llama_cpp"
    )
}

fn openai_chat_tool_definitions(
    selection: &ChatRuntimeSelection,
    enabled_tools: &[String],
) -> Vec<Value> {
    openai_chat_tool_definitions_with_mcp(selection, enabled_tools, &[])
}

fn openai_chat_tool_definitions_with_mcp(
    selection: &ChatRuntimeSelection,
    enabled_tools: &[String],
    mcp_tools: &[TutorbotMcpToolDefinition],
) -> Vec<Value> {
    if enabled_tools.is_empty() || !supports_native_chat_tools(selection) {
        return Vec::new();
    }
    let enabled = enabled_tools
        .iter()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    let mut definitions = plugin_tool_definitions()
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|definition| {
            let name = definition["name"].as_str()?;
            if !enabled.contains(name) {
                return None;
            }
            let mut properties = Map::new();
            let mut required = Vec::new();
            for parameter in definition["parameters"].as_array().into_iter().flatten() {
                let parameter_name = parameter["name"].as_str()?;
                if name == "rag" && parameter_name == "kb_name" {
                    continue;
                }
                let mut schema = Map::new();
                schema.insert(
                    "type".to_string(),
                    json!(parameter["type"].as_str().unwrap_or("string")),
                );
                if let Some(description) = parameter["description"].as_str() {
                    schema.insert("description".to_string(), json!(description));
                }
                if parameter["enum"].is_array() {
                    schema.insert("enum".to_string(), parameter["enum"].clone());
                }
                if !parameter["default"].is_null() {
                    schema.insert("default".to_string(), parameter["default"].clone());
                }
                if parameter["required"].as_bool() == Some(true) {
                    required.push(json!(parameter_name));
                }
                properties.insert(parameter_name.to_string(), Value::Object(schema));
            }
            Some(json!({
                "type": "function",
                "function": {
                    "name": name,
                    "description": definition["description"].as_str().unwrap_or_default(),
                    "parameters": {
                        "type": "object",
                        "properties": properties,
                        "required": required
                    }
                }
            }))
        })
        .collect::<Vec<_>>();
    definitions.extend(mcp_tools.iter().filter_map(|tool| {
        if !enabled.contains(tool.wrapped_name.as_str()) {
            return None;
        }
        Some(json!({
            "type": "function",
            "function": {
                "name": tool.wrapped_name,
                "description": tool.description,
                "parameters": tool.input_schema
            }
        }))
    }));
    definitions
}

async fn execute_chat_provider_tool_calls(
    state: &AppState,
    enabled_tools: &[String],
    knowledge_bases: &[String],
    fallback_query: &str,
    tool_calls: &[Value],
    mcp_tools: &[TutorbotMcpToolDefinition],
    auth_payload: Option<&AuthTokenPayload>,
) -> (Vec<Value>, Vec<ToolResult>, Vec<Value>) {
    let enabled = enabled_tools
        .iter()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    let allowed = plugin_tool_names();
    let mut tool_messages = Vec::new();
    let mut trace_results = Vec::new();
    let mut raw_results = Vec::new();

    for (index, tool_call) in tool_calls
        .iter()
        .take(MAX_PARALLEL_CHAT_TOOL_CALLS)
        .enumerate()
    {
        let name = tool_call["function"]["name"].as_str().unwrap_or_default();
        let tool_call_id = tool_call["id"]
            .as_str()
            .filter(|value| !value.trim().is_empty())
            .map(ToString::to_string)
            .unwrap_or_else(|| format!("call_{index}"));
        let params = chat_provider_tool_params(tool_call, name, knowledge_bases, fallback_query);
        let mcp_tool = mcp_tools.iter().find(|tool| tool.wrapped_name == name);
        let result = if enabled.contains(name) && allowed.contains(&name) {
            match plugin_tool_result(state, name, params.clone(), auth_payload).await {
                Ok(value) => value,
                Err((status, Json(error))) => {
                    let detail = error["detail"].as_str().unwrap_or("tool execution failed");
                    json!({
                        "success": false,
                        "content": format!("Error executing {name}: {detail}"),
                        "sources": [],
                        "metadata": {
                            "error": detail,
                            "status": status.as_u16()
                        }
                    })
                }
            }
        } else if enabled.contains(name) {
            if let Some(mcp_tool) = mcp_tool {
                execute_tutorbot_mcp_tool(mcp_tool, params.clone()).await
            } else {
                json!({
                    "success": false,
                    "content": format!("Error: Tool '{name}' not found."),
                    "sources": [],
                    "metadata": {
                        "error": "tool_not_found",
                        "tool": name
                    }
                })
            }
        } else {
            json!({
                "success": false,
                "content": format!("Tool '{name}' is not enabled for this chat turn."),
                "sources": [],
                "metadata": {
                    "error": "tool_not_enabled",
                    "tool": name
                }
            })
        };
        let content = result["content"]
            .as_str()
            .map(ToString::to_string)
            .unwrap_or_else(|| result.to_string());
        tool_messages.push(json!({
            "role": "tool",
            "tool_call_id": tool_call_id,
            "name": name,
            "content": content
        }));
        trace_results.push(ToolResult {
            adapter: "llm_tool_call".to_string(),
            action: name.to_string(),
            output: content,
            safe: result["success"].as_bool().unwrap_or(false),
        });
        raw_results.push(json!({
            "id": tool_call_id,
            "name": name,
            "arguments": params,
            "result": result
        }));
    }

    (tool_messages, trace_results, raw_results)
}

async fn execute_tutorbot_mcp_tool(tool: &TutorbotMcpToolDefinition, params: Value) -> Value {
    match tutorbot_mcp_json_rpc_request(
        &tool.server_config,
        "tools/call",
        json!({
            "name": tool.original_name,
            "arguments": params
        }),
    )
    .await
    {
        Ok(result) => {
            let content = tutorbot_mcp_result_content(&result);
            json!({
                "success": result["isError"].as_bool() != Some(true),
                "content": content,
                "sources": [],
                "metadata": {
                    "tool": tool.wrapped_name,
                    "server": tool.server_name,
                    "original_tool": tool.original_name
                }
            })
        }
        Err(error) => {
            let content = if error.starts_with("timeout after ") {
                format!("(MCP tool call timed out after {}s)", tool.tool_timeout)
            } else {
                "(MCP tool call failed: RuntimeError)".to_string()
            };
            json!({
                "success": false,
                "content": content,
                "sources": [],
                "metadata": {
                    "tool": tool.wrapped_name,
                    "server": tool.server_name,
                    "original_tool": tool.original_name,
                    "error": error
                }
            })
        }
    }
}

fn tutorbot_mcp_result_content(result: &Value) -> String {
    let parts = result["content"]
        .as_array()
        .into_iter()
        .flatten()
        .map(|block| {
            if block["type"].as_str() == Some("text")
                && let Some(text) = block["text"].as_str()
            {
                return text.to_string();
            }
            block.to_string()
        })
        .collect::<Vec<_>>();
    if parts.is_empty() {
        "(no output)".to_string()
    } else {
        parts.join("\n")
    }
}

fn chat_provider_tool_params(
    tool_call: &Value,
    tool_name: &str,
    knowledge_bases: &[String],
    fallback_query: &str,
) -> Value {
    let mut params = match &tool_call["function"]["arguments"] {
        Value::String(text) => parse_chat_provider_tool_arguments(text),
        Value::Object(_) => tool_call["function"]["arguments"].clone(),
        _ => json!({}),
    };
    if tool_name == "course_context"
        && let Some(object) = params.as_object_mut()
    {
        object.insert("knowledge_bases".to_string(), json!(knowledge_bases));
    }
    if tool_name == "rag"
        && let Some(object) = params.as_object_mut()
    {
        object.remove("kb_name");
        let query_is_empty = object
            .get("query")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .trim()
            .is_empty();
        if query_is_empty {
            object.insert("query".to_string(), json!(fallback_query));
        }
        if let Some(kb_name) = knowledge_bases.first() {
            object.insert("kb_name".to_string(), json!(kb_name));
        }
    }
    params
}

fn parse_chat_provider_tool_arguments(text: &str) -> Value {
    serde_json::from_str::<Value>(text)
        .or_else(|_| json5::from_str::<Value>(text))
        .ok()
        .filter(Value::is_object)
        .unwrap_or_else(|| json!({}))
}

fn normalized_chat_tool_calls(tool_calls: &[Value]) -> Vec<Value> {
    tool_calls
        .iter()
        .take(MAX_PARALLEL_CHAT_TOOL_CALLS)
        .enumerate()
        .map(|(index, tool_call)| {
            let mut normalized = tool_call.clone();
            if normalized["id"]
                .as_str()
                .unwrap_or_default()
                .trim()
                .is_empty()
            {
                normalized["id"] = json!(format!("call_{index}"));
            }
            if normalized["type"]
                .as_str()
                .unwrap_or_default()
                .trim()
                .is_empty()
            {
                normalized["type"] = json!("function");
            }
            normalized
        })
        .collect()
}

fn assistant_tool_call_message(response: &ChatProviderResponse, tool_calls: &[Value]) -> Value {
    json!({
        "role": "assistant",
        "content": response
            .content
            .as_ref()
            .map(|content| json!(content))
            .unwrap_or(Value::Null),
        "tool_calls": tool_calls
    })
}

fn merge_chat_provider_response_metadata(metadata: &mut Value, response: &ChatProviderResponse) {
    let Some(object) = metadata.as_object_mut() else {
        return;
    };
    if let Some(usage) = response.usage.as_ref() {
        object.insert("usage".to_string(), usage.clone());
    }
    if let Some(reasoning_content) = response.reasoning_content.as_ref() {
        object.insert("reasoning_content".to_string(), json!(reasoning_content));
    }
    if let Some(finish_reason) = response.finish_reason.as_ref() {
        object.insert("finish_reason".to_string(), json!(finish_reason));
    }
}

