fn retrieve(goal: &str) -> Vec<RetrievalChunk> {
    let goal_terms = goal.to_lowercase();
    let mut matches = knowledge_base()
        .into_iter()
        .filter(|chunk| {
            format!("{} {}", chunk.title, chunk.content)
                .to_lowercase()
                .split_whitespace()
                .any(|term| goal_terms.contains(term))
        })
        .collect::<Vec<_>>();

    if matches.len() < 2 {
        let existing = matches
            .iter()
            .map(|chunk| chunk.source_id.clone())
            .collect::<HashSet<_>>();
        for chunk in knowledge_base().into_iter().take(2) {
            if !existing.contains(&chunk.source_id) {
                matches.push(chunk);
            }
        }
    }

    matches
}

async fn retrieve_chat_context(
    state: &AppState,
    goal: &str,
    selected_knowledge_bases: &[String],
) -> Vec<RetrievalChunk> {
    if selected_knowledge_bases.is_empty() {
        return retrieve(goal);
    }

    let mut chunks = Vec::new();
    for name in selected_knowledge_bases {
        if name == BUILTIN_KNOWLEDGE_BASE {
            chunks.extend(retrieve(goal));
        } else {
            chunks.extend(retrieve_uploaded_knowledge_base(state, goal, name).await);
        }
    }

    dedupe_chunks(chunks).into_iter().take(5).collect()
}

async fn retrieve_chat_context_for_auth(
    state: &AppState,
    goal: &str,
    selected_knowledge_bases: &[String],
    payload: &AuthTokenPayload,
) -> Result<Vec<RetrievalChunk>, ApiError> {
    if selected_knowledge_bases.is_empty() {
        if payload.role == "admin" {
            return Ok(retrieve(goal));
        }
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "No knowledge base selected. Pass kb_name explicitly or set a default.",
        ));
    }

    let mut chunks = Vec::new();
    for name in selected_knowledge_bases {
        let access = resolve_knowledge_access(state, payload, name)?;
        match access {
            KnowledgeAccess::Builtin => chunks.extend(retrieve(goal)),
            KnowledgeAccess::Admin { name, .. } => {
                chunks.extend(retrieve_uploaded_knowledge_base(state, goal, &name).await);
            }
            KnowledgeAccess::User { name, user_id } => {
                let dir = user_knowledge_base_dir(state, &user_id, &name);
                chunks.extend(
                    retrieve_uploaded_knowledge_base_from_dir(state, goal, &name, &dir).await,
                );
            }
        }
    }

    Ok(dedupe_chunks(chunks).into_iter().take(5).collect())
}

async fn retrieve_uploaded_knowledge_base(
    state: &AppState,
    goal: &str,
    name: &str,
) -> Vec<RetrievalChunk> {
    if !knowledge_base_exists(state, name) {
        return Vec::new();
    }

    retrieve_uploaded_knowledge_base_from_dir(state, goal, name, &knowledge_base_dir(state, name))
        .await
}

async fn retrieve_uploaded_knowledge_base_from_dir(
    state: &AppState,
    goal: &str,
    name: &str,
    kb_dir: &FsPath,
) -> Vec<RetrievalChunk> {
    if !kb_dir.is_dir() {
        return Vec::new();
    }

    if let Some(chunks) = retrieve_indexed_knowledge_base_from_dir(state, goal, name, kb_dir).await
    {
        return chunks;
    }

    let query_terms = tokenize(goal);
    let mut scored = Vec::new();
    let Ok(entries) = fs::read_dir(knowledge_files_dir_at_dir(kb_dir)) else {
        return Vec::new();
    };

    for entry in entries.flatten() {
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        if !file_type.is_file() {
            continue;
        }

        let filename = entry.file_name().to_string_lossy().to_string();
        if !is_supported_knowledge_file(&filename) {
            continue;
        }

        let Ok(bytes) = fs::read(entry.path()) else {
            continue;
        };
        let Ok(text) = extract_knowledge_file_text(&filename, &bytes) else {
            continue;
        };
        let excerpt = compact_excerpt(&text, 900);
        if excerpt.is_empty() {
            continue;
        }

        let score = query_terms.intersection(&tokenize(&excerpt)).count();
        if score == 0 {
            continue;
        }
        scored.push((
            score,
            RetrievalChunk {
                source_id: format!("{name}/{filename}"),
                title: format!("{name} / {filename}"),
                content: excerpt,
                confidence: confidence_for_score(score).to_string(),
                source: Some(filename),
                page: None,
                chunk_id: None,
                score: Some(score as f64),
                provider: Some(DEFAULT_RAG_PROVIDER.to_string()),
            },
        ));
    }

    scored.sort_by(|left, right| {
        right
            .0
            .cmp(&left.0)
            .then_with(|| left.1.source_id.cmp(&right.1.source_id))
    });
    scored.into_iter().take(3).map(|(_, chunk)| chunk).collect()
}

async fn retrieve_indexed_knowledge_base_from_dir(
    state: &AppState,
    goal: &str,
    name: &str,
    kb_dir: &FsPath,
) -> Option<Vec<RetrievalChunk>> {
    let metadata = read_knowledge_metadata_at_dir(kb_dir).unwrap_or_else(|| json!({}));
    let versions = knowledge_index_versions(kb_dir, &metadata);
    let active = find_reusable_index_version(state, &versions, kb_dir)?;
    let version_dir = index_version_dir(kb_dir, active);
    let query_terms = tokenize(goal);
    if query_terms.is_empty() {
        return Some(Vec::new());
    }

    let chunk_index_path = version_dir.join("chunks.json");
    let Ok(text) = fs::read_to_string(chunk_index_path) else {
        return retrieve_llamaindex_docstore(name, &version_dir, &query_terms);
    };
    let Ok(index) = serde_json::from_str::<Value>(&text) else {
        return retrieve_llamaindex_docstore(name, &version_dir, &query_terms);
    };

    let indexed_chunks = index["chunks"]
        .as_array()
        .into_iter()
        .flatten()
        .collect::<Vec<_>>();
    if indexed_chunks
        .iter()
        .any(|chunk| chunk["embedding"].is_array())
    {
        let query_texts = vec![goal.to_string()];
        let query_embedding = match embed_knowledge_texts(state, &query_texts).await {
            Ok(mut embeddings) => embeddings.pop(),
            Err(_) => return Some(Vec::new()),
        };
        let Some(query_embedding) = query_embedding else {
            return Some(Vec::new());
        };
        let mut scored = indexed_chunks
            .iter()
            .filter_map(|chunk| {
                let content = chunk["content"].as_str()?;
                let title = chunk["title"].as_str().unwrap_or_default();
                let source = chunk["source"].as_str().unwrap_or_default();
                let embedding = embedding_from_value(&chunk["embedding"])?;
                let score = cosine_similarity(&query_embedding, &embedding)?;
                let source_id = chunk["source_id"]
                    .as_str()
                    .map(ToString::to_string)
                    .unwrap_or_else(|| format!("{name}/{source}"));
                let chunk_id = chunk["chunk_id"].as_str().map(ToString::to_string);
                let focused_content = query_focused_excerpt(content, &query_terms, 900);
                Some((
                    score,
                    source_id.clone(),
                    RetrievalChunk {
                        source_id,
                        title: title.to_string(),
                        content: focused_content,
                        confidence: confidence_for_similarity(score).to_string(),
                        source: (!source.is_empty()).then(|| source.to_string()),
                        page: chunk["page"].as_str().map(ToString::to_string),
                        chunk_id,
                        score: Some(score),
                        provider: Some(
                            chunk["provider"]
                                .as_str()
                                .unwrap_or(DEFAULT_RAG_PROVIDER)
                                .to_string(),
                        ),
                    },
                ))
            })
            .collect::<Vec<_>>();
        scored.sort_by(|left, right| {
            right
                .0
                .partial_cmp(&left.0)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| left.1.cmp(&right.1))
        });
        return Some(
            scored
                .into_iter()
                .take(5)
                .map(|(_, _, chunk)| chunk)
                .collect(),
        );
    }

    let mut scored = index["chunks"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|chunk| {
            let content = chunk["content"].as_str()?;
            let title = chunk["title"].as_str().unwrap_or_default();
            let source = chunk["source"].as_str().unwrap_or_default();
            let score = query_terms
                .intersection(&tokenize(&format!("{title} {source} {content}")))
                .count();
            if score == 0 {
                return None;
            }
            let source_id = chunk["source_id"]
                .as_str()
                .map(ToString::to_string)
                .unwrap_or_else(|| format!("{name}/{source}"));
            let chunk_id = chunk["chunk_id"].as_str().map(ToString::to_string);
            let focused_content = query_focused_excerpt(content, &query_terms, 900);
            Some((
                score,
                source_id.clone(),
                RetrievalChunk {
                    source_id,
                    title: title.to_string(),
                    content: focused_content,
                    confidence: confidence_for_score(score).to_string(),
                    source: (!source.is_empty()).then(|| source.to_string()),
                    page: chunk["page"].as_str().map(ToString::to_string),
                    chunk_id,
                    score: Some(score as f64),
                    provider: Some(
                        chunk["provider"]
                            .as_str()
                            .unwrap_or(DEFAULT_RAG_PROVIDER)
                            .to_string(),
                    ),
                },
            ))
        })
        .collect::<Vec<_>>();
    scored.sort_by(|left, right| right.0.cmp(&left.0).then_with(|| left.1.cmp(&right.1)));
    Some(
        scored
            .into_iter()
            .take(5)
            .map(|(_, _, chunk)| chunk)
            .collect(),
    )
}

fn find_reusable_index_version<'a>(
    state: &AppState,
    versions: &'a [Value],
    kb_dir: &FsPath,
) -> Option<&'a Value> {
    find_active_index_version(state, versions).or_else(|| {
        versions.iter().rev().find(|version| {
            version["ready"].as_bool().unwrap_or(false) && {
                let version_dir = index_version_dir(kb_dir, version);
                version_dir.join("chunks.json").is_file()
                    || version_dir.join("docstore.json").is_file()
            }
        })
    })
}

fn index_version_dir(kb_dir: &FsPath, version: &Value) -> PathBuf {
    version["version_path"]
        .as_str()
        .or_else(|| version["storage_path"].as_str())
        .map(PathBuf::from)
        .unwrap_or_else(|| kb_dir.join(version["version"].as_str().unwrap_or("version-1")))
}

fn retrieve_llamaindex_docstore(
    name: &str,
    version_dir: &FsPath,
    query_terms: &HashSet<String>,
) -> Option<Vec<RetrievalChunk>> {
    let text = fs::read_to_string(version_dir.join("docstore.json")).ok()?;
    let docstore = serde_json::from_str::<Value>(&text).ok()?;
    let nodes = docstore["docstore/data"].as_object()?;
    let mut scored = nodes
        .iter()
        .filter_map(|(node_key, node)| {
            let data = llamaindex_node_data(node)?;
            let content = data["text"].as_str()?;
            let metadata = &data["metadata"];
            let source = metadata["file_name"]
                .as_str()
                .filter(|value| !value.trim().is_empty())
                .map(ToString::to_string)
                .or_else(|| {
                    metadata["file_path"]
                        .as_str()
                        .and_then(|path| FsPath::new(path).file_name())
                        .and_then(|name| name.to_str())
                        .map(ToString::to_string)
                })
                .unwrap_or_else(|| format!("{node_key}.txt"));
            let score = query_terms
                .intersection(&tokenize(&format!("{source} {content}")))
                .count();
            if score == 0 {
                return None;
            }
            let node_id = data["id_"]
                .as_str()
                .or_else(|| data["id"].as_str())
                .unwrap_or(node_key)
                .to_string();
            let source_id = format!("{name}/{source}");
            let focused_content = query_focused_excerpt(content, query_terms, 900);
            Some((
                score,
                source_id.clone(),
                RetrievalChunk {
                    source_id,
                    title: source.clone(),
                    content: focused_content,
                    confidence: confidence_for_score(score).to_string(),
                    source: Some(source),
                    page: None,
                    chunk_id: Some(node_id),
                    score: Some(score as f64),
                    provider: Some(DEFAULT_RAG_PROVIDER.to_string()),
                },
            ))
        })
        .collect::<Vec<_>>();
    scored.sort_by(|left, right| right.0.cmp(&left.0).then_with(|| left.1.cmp(&right.1)));
    Some(
        scored
            .into_iter()
            .take(5)
            .map(|(_, _, chunk)| chunk)
            .collect(),
    )
}

fn llamaindex_node_data(node: &Value) -> Option<Value> {
    let data = &node["__data__"];
    if data.is_object() {
        return Some(data.clone());
    }
    data.as_str()
        .and_then(|text| serde_json::from_str::<Value>(text).ok())
}

fn dedupe_chunks(chunks: Vec<RetrievalChunk>) -> Vec<RetrievalChunk> {
    let mut seen = HashSet::new();
    let mut deduped = Vec::new();

    for chunk in chunks {
        if seen.insert(chunk.source_id.clone()) {
            deduped.push(chunk);
        }
    }

    deduped
}

fn compact_excerpt(text: &str, max_chars: usize) -> String {
    let normalized = text.split_whitespace().collect::<Vec<_>>().join(" ");
    let mut excerpt = normalized.chars().take(max_chars).collect::<String>();
    if normalized.chars().count() > max_chars {
        excerpt.push_str("...");
    }
    excerpt
}

fn query_focused_excerpt(text: &str, query_terms: &HashSet<String>, max_chars: usize) -> String {
    let mut best_score = 0;
    let mut best_segment = text;
    for segment in text
        .split(['.', '!', '?', '\n'])
        .map(str::trim)
        .filter(|segment| !segment.is_empty())
    {
        let score = query_terms.intersection(&tokenize(segment)).count();
        if score > best_score {
            best_score = score;
            best_segment = segment;
        }
    }
    if best_score == 0 {
        compact_excerpt(text, max_chars)
    } else {
        compact_excerpt(best_segment, max_chars)
    }
}

fn confidence_for_score(score: usize) -> &'static str {
    match score {
        0 => "low",
        1 => "medium",
        _ => "high",
    }
}

fn confidence_for_similarity(score: f64) -> &'static str {
    if score >= 0.75 {
        "high"
    } else if score >= 0.25 {
        "medium"
    } else {
        "low"
    }
}

fn embedding_from_value(value: &Value) -> Option<Vec<f64>> {
    let vector = value
        .as_array()?
        .iter()
        .map(Value::as_f64)
        .collect::<Option<Vec<_>>>()?;
    if vector.is_empty() || vector.iter().any(|value| !value.is_finite()) {
        None
    } else {
        Some(vector)
    }
}

fn cosine_similarity(left: &[f64], right: &[f64]) -> Option<f64> {
    if left.is_empty() || left.len() != right.len() {
        return None;
    }
    let dot = left
        .iter()
        .zip(right)
        .map(|(left, right)| left * right)
        .sum::<f64>();
    let left_norm = left.iter().map(|value| value * value).sum::<f64>().sqrt();
    let right_norm = right.iter().map(|value| value * value).sum::<f64>().sqrt();
    if left_norm == 0.0 || right_norm == 0.0 {
        None
    } else {
        Some(dot / (left_norm * right_norm))
    }
}

